-- ===== 0086_own_gear_photo.sql =====
-- RigTrack: moja fotka a moja technika priamo z „Vyberte firmu“ (3.7).
-- 1) Fotku do svojej karty zamestnanca si nahrá každý člen firmy (aj pomocník alebo divák) – len pod
--    názvom „staff-<id mojej karty>-…“ v priečinku firmy.
-- 2) Vlastnú techniku a vlastný case / rack si člen založí sám vo zvolenej firme; vlastníkom je jeho karta.

drop policy if exists equipment_photos_own_staff_insert on storage.objects;
create policy equipment_photos_own_staff_insert on storage.objects for insert to authenticated
  with check (
    bucket_id = 'equipment-photos'
    and exists (
      select 1 from public.staff s
      where s.company_id::text = (storage.foldername(objects.name))[1]
        and s.member_id = auth.uid()
        and storage.filename(objects.name) like 'staff-' || s.id::text || '-%'
    )
  );
drop policy if exists equipment_photos_own_staff_delete on storage.objects;
create policy equipment_photos_own_staff_delete on storage.objects for delete to authenticated
  using (
    bucket_id = 'equipment-photos'
    and exists (
      select 1 from public.staff s
      where s.company_id::text = (storage.foldername(objects.name))[1]
        and s.member_id = auth.uid()
        and storage.filename(objects.name) like 'staff-' || s.id::text || '-%'
    )
  );

/** Moja karta zamestnanca vo firme; ak ešte nie je, založí sa. */
create or replace function public.my_staff_card(_company_id uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _card uuid;
begin
  if not public.is_company_member(_company_id) then
    raise exception 'Nie ste členom tejto firmy' using errcode = 'insufficient_privilege';
  end if;
  select id into _card from public.staff where company_id = _company_id and member_id = auth.uid();
  if _card is null then
    insert into public.staff (company_id, member_id, name) values (_company_id, auth.uid(), '') returning id into _card;
  end if;
  return _card;
end;
$$;

/** Založí moju vlastnú techniku vo firme (vlastník = moja karta). */
create or replace function public.create_own_equipment(_company_id uuid, _name text, _kind text, _quantity integer, _manufacturer text default '', _model text default '')
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _id uuid;
begin
  insert into public.equipment (company_id, name, kind, quantity, manufacturer, model, owner_staff_id)
  values (_company_id, trim(_name), _kind, greatest(1, coalesce(_quantity, 1)), coalesce(trim(_manufacturer), ''), coalesce(trim(_model), ''), public.my_staff_card(_company_id))
  returning id into _id;
  return _id;
end;
$$;

/** Založí môj vlastný case / rack vo firme (vlastník = moja karta). */
create or replace function public.create_own_case(_company_id uuid, _name text, _note text default '')
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _id uuid;
begin
  insert into public.cases (company_id, name, note, owner_staff_id)
  values (_company_id, trim(_name), coalesce(trim(_note), ''), public.my_staff_card(_company_id))
  returning id into _id;
  return _id;
end;
$$;

revoke execute on function public.my_staff_card(uuid), public.create_own_equipment(uuid, text, text, integer, text, text), public.create_own_case(uuid, text, text) from public, anon;
grant execute on function public.my_staff_card(uuid), public.create_own_equipment(uuid, text, text, integer, text, text), public.create_own_case(uuid, text, text) to authenticated;

-- 3) Zariadenia hostí (napr. hosťujúci zvukár): meno, kontakt, zariadenie, MAC, prípadne pevná IP a sieť.
--    V IP tabuľke ich vidí a zapisuje, kto upravuje techniku (kontakt je osobný údaj).
create table if not exists public.guest_devices (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  person_name text not null check (char_length(trim(person_name)) between 1 and 120),
  contact text not null default '' check (char_length(contact) <= 120),
  device_name text not null default '' check (char_length(device_name) <= 80),
  mac text not null default '' check (mac = '' or mac ~ '^([0-9A-F]{2}:){5}[0-9A-F]{2}$'),
  ip text not null default '' check (char_length(ip) <= 45),
  network_id uuid references public.wifi_networks (id) on delete set null,
  note text not null default '' check (char_length(note) <= 300),
  valid_until date,
  created_by uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  check (mac <> '' or ip <> '')
);
create index if not exists guest_devices_company_idx on public.guest_devices (company_id);

alter table public.guest_devices enable row level security;
drop policy if exists guest_devices_select on public.guest_devices;
drop policy if exists guest_devices_write on public.guest_devices;
create policy guest_devices_select on public.guest_devices for select to authenticated using (public.can(company_id, 'equipment.edit'));
create policy guest_devices_write on public.guest_devices for all to authenticated
  using (public.can(company_id, 'equipment.edit')) with check (public.can(company_id, 'equipment.edit'));
revoke all on public.guest_devices from anon, authenticated;
grant select, insert, update, delete on public.guest_devices to authenticated;

-- 4) Časť kusov do case: zo 16 svetiel dám 2 do case – vznikne nová položka s 2 ks v case, pôvodná má 14.
--    Pri technike s očíslovanými kusmi idú do case prvé čísla. Inventárne číslo ostáva pôvodnej položke.
create or replace function public.split_equipment_into_case(_equipment_id uuid, _case_id uuid, _count integer)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  e public.equipment%rowtype;
  _id uuid;
  _units integer[];
begin
  select * into e from public.equipment where id = _equipment_id and deleted_at is null;
  if e.id is null or not public.can(e.company_id, 'equipment.edit') then
    raise exception 'Túto techniku nemôžete meniť' using errcode = 'insufficient_privilege';
  end if;
  if _case_id is not null and not exists (select 1 from public.cases where id = _case_id and company_id = e.company_id and deleted_at is null) then
    raise exception 'Case nepatrí tejto firme' using errcode = 'insufficient_privilege';
  end if;
  if _count is null or _count < 1 then
    raise exception 'Počet musí byť aspoň 1' using errcode = 'check_violation';
  end if;
  if _count >= e.quantity then
    update public.equipment set case_id = _case_id, label_role = null where id = e.id;
    return e.id;
  end if;

  _units := coalesce(e.unit_ids, '{}');
  _id := gen_random_uuid();
  insert into public.equipment
  select (jsonb_populate_record(null::public.equipment,
    to_jsonb(e) || jsonb_build_object(
      'id', _id,
      'case_id', _case_id,
      'label_role', null,
      'quantity', _count,
      'inventory_number', '',
      'unit_ids', case when cardinality(_units) > 0 then to_jsonb(_units[1:_count]) else to_jsonb(_units) end,
      'shared_from', null,
      'created_at', now(),
      'updated_at', now()
    ))).*;
  update public.equipment
    set quantity = e.quantity - _count,
        unit_ids = case when cardinality(_units) > 0 then _units[_count + 1:] else unit_ids end
    where id = e.id;
  return _id;
end;
$$;

-- 5) Viac case naraz: „Case svetlo 1“ až „Case svetlo 8“, voliteľne podľa šablóny a s rovnomerne
--    rozdelenou technikou (napr. 16 svetiel → 2 do každého).
create or replace function public.create_cases_bulk(
  _company_id uuid, _base_name text, _count integer, _start integer default 1, _template_id uuid default null,
  _equipment_id uuid default null, _per_case integer default null
)
returns uuid[] language plpgsql security definer set search_path = '' as $$
declare
  t public.case_templates%rowtype;
  _ids uuid[] := '{}';
  _case uuid;
  _available integer;
  i integer;
begin
  if not public.can(_company_id, 'cases.edit') then
    raise exception 'Nemôžete pridávať case' using errcode = 'insufficient_privilege';
  end if;
  if _count is null or _count < 1 or _count > 100 then
    raise exception 'Počet case musí byť 1 až 100' using errcode = 'check_violation';
  end if;
  if _template_id is not null then
    select * into t from public.case_templates where id = _template_id and company_id = _company_id;
  end if;
  if _equipment_id is not null then
    if not public.can(_company_id, 'equipment.edit') then
      raise exception 'Techniku nemôžete meniť' using errcode = 'insufficient_privilege';
    end if;
    select quantity into _available from public.equipment where id = _equipment_id and company_id = _company_id and deleted_at is null;
    if _available is null or coalesce(_per_case, 0) < 1 or _available < _count * _per_case then
      raise exception 'Nie je dosť kusov: treba %, je %', _count * coalesce(_per_case, 0), coalesce(_available, 0) using errcode = 'check_violation';
    end if;
  end if;

  for i in 0 .. _count - 1 loop
    insert into public.cases (company_id, name, label_number, label_category, weight_kg, width_cm, length_cm, depth_cm)
    values (_company_id, trim(_base_name) || ' ' || (coalesce(_start, 1) + i), (coalesce(_start, 1) + i)::text,
            coalesce(t.label_category, ''), t.weight_kg, t.width_cm, t.length_cm, t.depth_cm)
    returning id into _case;
    _ids := _ids || _case;
    if _equipment_id is not null then
      perform public.split_equipment_into_case(_equipment_id, _case, _per_case);
    end if;
  end loop;
  return _ids;
end;
$$;

revoke execute on function public.split_equipment_into_case(uuid, uuid, integer), public.create_cases_bulk(uuid, text, integer, integer, uuid, uuid, integer) from public, anon;
grant execute on function public.split_equipment_into_case(uuid, uuid, integer), public.create_cases_bulk(uuid, text, integer, integer, uuid, uuid, integer) to authenticated;

-- 6) Profil → karty zamestnanca (telefón, e-mail, narodeniny, meniny, vodičák, sociálne siete): funkcie aj
--    spúšťače nanovo (ak by v databáze chýbali alebo boli staršie) a jednorazové dorovnanie všetkých kariet.
create or replace function public.apply_personal_profile(_user_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  p public.personal_profiles%rowtype;
begin
  select * into p from public.personal_profiles where user_id = _user_id;
  if not found then return; end if;
  update public.staff s
    set phone = p.phone, email = p.email, birth_date = p.birth_date, name_day = p.name_day, licences = p.licences,
        socials = case when p.socials = '{}'::jsonb then s.socials else p.socials end
    where s.member_id = _user_id and s.sync_profile;
  if p.home_address <> '' then
    insert into public.member_homes (company_id, user_id, address, lat, lon, updated_at)
      select m.company_id, _user_id, p.home_address, p.home_lat, p.home_lon, now()
      from public.company_members m where m.user_id = _user_id
    on conflict (company_id, user_id) do update set address = excluded.address, lat = excluded.lat, lon = excluded.lon, updated_at = now();
  end if;
end;
$$;
revoke execute on function public.apply_personal_profile(uuid) from public, anon, authenticated;

create or replace function public.fill_staff_from_profile()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  p public.personal_profiles%rowtype;
begin
  if new.member_id is null or not new.sync_profile then return new; end if;
  if tg_op = 'UPDATE' and old.sync_profile then return new; end if;
  select * into p from public.personal_profiles where user_id = new.member_id;
  if found then
    new.phone := p.phone;
    new.email := p.email;
    new.birth_date := p.birth_date;
    new.name_day := p.name_day;
    new.licences := p.licences;
    if p.socials <> '{}'::jsonb then new.socials := p.socials; end if;
  end if;
  return new;
end;
$$;
revoke execute on function public.fill_staff_from_profile() from public, anon, authenticated;

create or replace function public.personal_profile_changed()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  perform public.apply_personal_profile(new.user_id);
  return new;
end;
$$;
revoke execute on function public.personal_profile_changed() from public, anon, authenticated;
drop trigger if exists personal_profiles_apply on public.personal_profiles;
create trigger personal_profiles_apply after insert or update on public.personal_profiles
  for each row execute function public.personal_profile_changed();
drop trigger if exists staff_fill_from_profile on public.staff;
create trigger staff_fill_from_profile before insert or update of sync_profile on public.staff
  for each row execute function public.fill_staff_from_profile();

select public.apply_personal_profile(user_id) from public.personal_profiles;

-- ===== 0087_profile_skills.sql =====
-- RigTrack: zručnosti v osobnom profile (3.8).
-- Čo človek vie ovládať (napr. Avolites, GrandMA, Crown, práca vo výškach) zadá raz v Mojom profile;
-- prenesie sa do jeho kariet zamestnanca vo všetkých firmách (kým má karta zapnuté „brať z profilu“).

alter table public.personal_profiles add column if not exists skills text not null default '' check (char_length(skills) <= 500);
grant update (skills) on public.personal_profiles to authenticated;

create or replace function public.apply_personal_profile(_user_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  p public.personal_profiles%rowtype;
begin
  select * into p from public.personal_profiles where user_id = _user_id;
  if not found then return; end if;
  update public.staff s
    set phone = p.phone, email = p.email, birth_date = p.birth_date, name_day = p.name_day, licences = p.licences,
        socials = case when p.socials = '{}'::jsonb then s.socials else p.socials end,
        skills = case when p.skills = '' then s.skills else p.skills end
    where s.member_id = _user_id and s.sync_profile;
  if p.home_address <> '' then
    insert into public.member_homes (company_id, user_id, address, lat, lon, updated_at)
      select m.company_id, _user_id, p.home_address, p.home_lat, p.home_lon, now()
      from public.company_members m where m.user_id = _user_id
    on conflict (company_id, user_id) do update set address = excluded.address, lat = excluded.lat, lon = excluded.lon, updated_at = now();
  end if;
end;
$$;
revoke execute on function public.apply_personal_profile(uuid) from public, anon, authenticated;

create or replace function public.fill_staff_from_profile()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  p public.personal_profiles%rowtype;
begin
  if new.member_id is null or not new.sync_profile then return new; end if;
  if tg_op = 'UPDATE' and old.sync_profile then return new; end if;
  select * into p from public.personal_profiles where user_id = new.member_id;
  if found then
    new.phone := p.phone;
    new.email := p.email;
    new.birth_date := p.birth_date;
    new.name_day := p.name_day;
    new.licences := p.licences;
    if p.socials <> '{}'::jsonb then new.socials := p.socials; end if;
    if p.skills <> '' then new.skills := p.skills; end if;
  end if;
  return new;
end;
$$;
revoke execute on function public.fill_staff_from_profile() from public, anon, authenticated;

-- ===== 0088_partner_details.sql =====
-- RigTrack: Firmy a kontakty podrobnejšie (3.8).
-- 1) Firma: obchodné meno (oficiálny názov, ak sa líši od bežného), IČ DPH a CEO.
-- 2) Kontakt: dátum narodenia.
-- 3) Prepojenie s firmou, ktorá už v RigTracku je: nájde sa podľa IČO alebo presného názvu / obchodného mena
--    a partner sa s ňou prepojí (namiesto zakladania druhej firmy).

alter table public.partners add column if not exists legal_name text not null default '' check (char_length(legal_name) <= 160);
alter table public.partners add column if not exists ic_dph text not null default '' check (char_length(ic_dph) <= 20);
alter table public.partners add column if not exists ceo text not null default '' check (char_length(ceo) <= 120);
grant update (legal_name, ic_dph, ceo) on public.partners to authenticated;

alter table public.partner_contacts add column if not exists birth_date date;
grant update (birth_date) on public.partner_contacts to authenticated;

/** Firmy v RigTracku s rovnakým IČO, alebo s presne rovnakým názvom či obchodným menom (len názov a id). */
create or replace function public.find_rigtrack_companies(_ico text, _name text, _legal_name text default '')
returns table (id uuid, name text, legal_name text)
language sql stable security definer set search_path = '' as $$
  select c.id, c.name, coalesce(p.legal_name, '')
  from public.companies c
  left join public.company_profile p on p.company_id = c.id
  where auth.uid() is not null
    and (
      (length(regexp_replace(coalesce(_ico, ''), '\s', '', 'g')) >= 6
        and regexp_replace(coalesce(p.ico, ''), '\s', '', 'g') = regexp_replace(_ico, '\s', '', 'g'))
      or (trim(coalesce(_name, '')) <> '' and (lower(trim(c.name)) = lower(trim(_name)) or lower(trim(coalesce(p.legal_name, ''))) = lower(trim(_name))))
      or (trim(coalesce(_legal_name, '')) <> '' and (lower(trim(c.name)) = lower(trim(_legal_name)) or lower(trim(coalesce(p.legal_name, ''))) = lower(trim(_legal_name))))
    )
  order by c.name
  limit 5;
$$;
revoke execute on function public.find_rigtrack_companies(text, text, text) from public, anon;
grant execute on function public.find_rigtrack_companies(text, text, text) to authenticated;

/** Prepojí firmu z adresára s firmou v RigTracku (alebo väzbu zruší, keď _company_id je null). */
create or replace function public.link_partner_company(_partner_id uuid, _company_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  _owner uuid;
begin
  select company_id into _owner from public.partners where id = _partner_id;
  if _owner is null or not public.can(_owner, 'events.edit') then
    raise exception 'Firma neexistuje alebo nemáte oprávnenie' using errcode = 'insufficient_privilege';
  end if;
  if _company_id = _owner then
    raise exception 'Firmu nemožno prepojiť samu so sebou' using errcode = 'check_violation';
  end if;
  update public.partners set linked_company_id = _company_id, uses_app = (_company_id is not null) or uses_app where id = _partner_id;
end;
$$;
revoke execute on function public.link_partner_company(uuid, uuid) from public, anon;
grant execute on function public.link_partner_company(uuid, uuid) to authenticated;

/** Založí partnerovi firmu v RigTracku; prenesie aj obchodné meno, IČ DPH a CEO. */
create or replace function public.create_partner_company(_partner_id uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _partner public.partners;
  _id uuid;
begin
  select * into _partner from public.partners p where p.id = _partner_id;
  if not found or not public.can(_partner.company_id, 'events.edit') then
    raise exception 'Firma neexistuje alebo nemáte oprávnenie' using errcode = 'insufficient_privilege';
  end if;
  if _partner.linked_company_id is not null then
    return _partner.linked_company_id;
  end if;
  insert into public.companies (name, created_by, founded_by) values (left(trim(_partner.name), 120), auth.uid(), _partner.company_id) returning id into _id;
  insert into public.company_members (company_id, user_id, role) values (_id, auth.uid(), 'admin');
  insert into public.company_profile (company_id, legal_name, ico, dic, ic_dph, address, ceo_name)
  values (_id, left(coalesce(nullif(trim(_partner.legal_name), ''), _partner.name), 160), left(_partner.ico, 20), left(_partner.dic, 20),
          left(_partner.ic_dph, 20), left(_partner.address, 200), left(_partner.ceo, 120));
  update public.partners set linked_company_id = _id, uses_app = true where id = _partner_id;
  return _id;
end;
$$;
revoke execute on function public.create_partner_company(uuid) from public, anon;
grant execute on function public.create_partner_company(uuid) to authenticated;

-- 4) Ako sa zobrazuje logo firmy: automaticky (podľa farieb), pôvodné farby bez podložky, s bielou podložkou,
--    vždy biele alebo vždy čierne.
alter table public.companies add column if not exists logo_style text not null default 'auto'
  check (logo_style in ('auto', 'original', 'plate', 'white', 'black'));
grant update (logo_style) on public.companies to authenticated;

-- 5) Push bez ručného Database Webhooku: nový riadok v notifications pošle databáza sama funkcii send-push
--    (pg_net). Adresa funkcie a tajomstvo sú vo Vault (vault.create_secret – návod v Nastaveniach → Push);
--    kým tam nie sú, nič sa neposiela. Kto už má Database Webhook, nech ho zmaže, inak príde upozornenie dvakrát.
do $$
begin
  create schema if not exists extensions;
  create extension if not exists pg_net with schema extensions;
exception when others then
  raise notice 'pg_net nie je k dispozícii – push sa bude posielať len cez Database Webhook';
end;
$$;

create or replace function public.notification_send_push()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  _url text;
  _secret text;
begin
  begin
    execute 'select decrypted_secret from vault.decrypted_secrets where name = $1' into _url using 'push_function_url';
    execute 'select decrypted_secret from vault.decrypted_secrets where name = $1' into _secret using 'push_webhook_secret';
    if coalesce(_url, '') = '' or coalesce(_secret, '') = '' then return new; end if;
    execute 'select net.http_post(url := $1, headers := $2, body := $3)'
      using _url, jsonb_build_object('Content-Type', 'application/json', 'x-webhook-secret', _secret), jsonb_build_object('record', to_jsonb(new));
  exception when others then
    -- Chýba Vault alebo pg_net: upozornenie ostane v appke, len nepríde na mobil.
    return new;
  end;
  return new;
end;
$$;
revoke execute on function public.notification_send_push() from public, anon, authenticated;
drop trigger if exists notifications_send_push on public.notifications;
create trigger notifications_send_push after insert on public.notifications
  for each row execute function public.notification_send_push();

/** Je push v databáze nastavený? (len áno / nie, žiadne tajomstvá) */
create or replace function public.push_setup_status()
returns table (has_pg_net boolean, has_url boolean, has_secret boolean)
language plpgsql stable security definer set search_path = '' as $$
declare
  _url boolean := false;
  _secret boolean := false;
begin
  begin
    execute 'select exists (select 1 from vault.decrypted_secrets where name = $1 and decrypted_secret <> '''')' into _url using 'push_function_url';
    execute 'select exists (select 1 from vault.decrypted_secrets where name = $1 and decrypted_secret <> '''')' into _secret using 'push_webhook_secret';
  exception when others then
    null;
  end;
  return query select exists (select 1 from pg_extension where extname = 'pg_net'), _url, _secret;
end;
$$;
revoke execute on function public.push_setup_status() from public, anon;
grant execute on function public.push_setup_status() to authenticated;

-- ===== 0089_responsibilities.sql =====
-- RigTrack: zodpovedné osoby (3.9).
-- Admin nastaví zodpovednosti, napr. „Svetlá“ (všetka technika druhu svetlo), „Zvuk“ alebo „Case LED“
-- (konkrétne case), ľudí, ktorí za ne zodpovedajú, a čo majú robiť: odčítať prevádzkové hodiny každých N dní,
-- skontrolovať case každých N dní. Zodpovedný to vidí na Prehľade a raz denne dostane upozornenie
-- (ak je v databáze plánovač pg_cron; inak len na Prehľade).

create table if not exists public.responsibilities (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  name text not null check (char_length(trim(name)) between 1 and 80),
  kinds text[] not null default '{}',
  case_ids uuid[] not null default '{}',
  member_ids uuid[] not null default '{}',
  hours_every_days integer check (hours_every_days between 1 and 365),
  check_every_days integer check (check_every_days between 1 and 365),
  note text not null default '' check (char_length(note) <= 500),
  created_at timestamptz not null default now()
);
create index if not exists responsibilities_company_idx on public.responsibilities (company_id);

alter table public.responsibilities enable row level security;
drop policy if exists responsibilities_select on public.responsibilities;
drop policy if exists responsibilities_write on public.responsibilities;
create policy responsibilities_select on public.responsibilities for select to authenticated using (public.is_company_member(company_id));
create policy responsibilities_write on public.responsibilities for all to authenticated
  using (public.has_role(company_id, 'admin')) with check (public.has_role(company_id, 'admin'));
revoke all on public.responsibilities from anon, authenticated;
grant select, insert, update, delete on public.responsibilities to authenticated;

/**
 * Čo je pri zodpovednostiach po termíne: hodiny (technika s „sledovať hodiny“, ktorej posledné odčítanie
 * je staršie ako N dní) a kontroly (case skontrolované naposledy pred viac ako N dňami alebo nikdy).
 * Rozsah: technika daného druhu alebo v zvolených case; case zvolené alebo s takou technikou.
 */
create or replace function public.responsibility_due(_company_id uuid)
returns table (responsibility_id uuid, name text, task text, due_count integer, items text[], member_ids uuid[])
language sql stable security definer set search_path = '' as $$
  with r as (
    select * from public.responsibilities where company_id = _company_id
  ),
  scope_equipment as (
    select r.id as rid, e.id, e.name, e.case_id
    from r join public.equipment e on e.company_id = r.company_id
    where e.deleted_at is null and e.status <> 'retired' and (e.kind = any (r.kinds) or e.case_id = any (r.case_ids))
  ),
  hours as (
    select se.rid, se.name, (select max(h.read_on) from public.equipment_hour_readings h where h.equipment_id = se.id) as last_read
    from scope_equipment se
    join public.equipment e on e.id = se.id
    where coalesce(e.attributes ->> 'trackHours', '') = 'true'
  ),
  scope_cases as (
    select distinct r.id as rid, c.id, c.name
    from r join public.cases c on c.company_id = r.company_id
    where c.deleted_at is null
      and (c.id = any (r.case_ids) or exists (select 1 from scope_equipment se where se.rid = r.id and se.case_id = c.id))
  ),
  checks as (
    select sc.rid, sc.name, (select max(k.checked_at) from public.case_checks k where k.case_id = sc.id) as last_check
    from scope_cases sc
  )
  select r.id, r.name, 'hours', count(*)::integer, (array_agg(h.name order by h.last_read nulls first))[1:10], r.member_ids
  from r join hours h on h.rid = r.id
  where r.hours_every_days is not null and (h.last_read is null or h.last_read < current_date - r.hours_every_days)
  group by r.id, r.name, r.member_ids
  union all
  select r.id, r.name, 'check', count(*)::integer, (array_agg(k.name order by k.last_check nulls first))[1:10], r.member_ids
  from r join checks k on k.rid = r.id
  where r.check_every_days is not null and (k.last_check is null or k.last_check < now() - make_interval(days => r.check_every_days))
  group by r.id, r.name, r.member_ids;
$$;
revoke execute on function public.responsibility_due(uuid) from public, anon, authenticated;

/** Moje úlohy zo zodpovedností vo firme (len kde som medzi zodpovednými). */
create or replace function public.my_responsibility_tasks(_company_id uuid)
returns table (responsibility_id uuid, name text, task text, due_count integer, items text[])
language sql stable security definer set search_path = '' as $$
  select d.responsibility_id, d.name, d.task, d.due_count, d.items
  from public.responsibility_due(_company_id) d
  where public.is_company_member(_company_id) and auth.uid() = any (d.member_ids);
$$;
revoke execute on function public.my_responsibility_tasks(uuid) from public, anon;
grant execute on function public.my_responsibility_tasks(uuid) to authenticated;

-- Pripomienky: každému zodpovednému raz za 7 dní za každú úlohu po termíne (push cez notifications).
create table if not exists public.responsibility_reminders (
  responsibility_id uuid not null references public.responsibilities (id) on delete cascade,
  member_id uuid not null references public.profiles (id) on delete cascade,
  task text not null,
  reminded_on date not null default current_date,
  primary key (responsibility_id, member_id, task)
);
alter table public.responsibility_reminders enable row level security;
revoke all on public.responsibility_reminders from anon, authenticated;

create or replace function public.remind_responsibilities()
returns integer language plpgsql security definer set search_path = '' as $$
declare
  d record;
  _member uuid;
  _company uuid;
  _count integer := 0;
begin
  for _company in select distinct company_id from public.responsibilities loop
    for d in select * from public.responsibility_due(_company) loop
      foreach _member in array d.member_ids loop
        continue when not exists (select 1 from public.company_members m where m.company_id = _company and m.user_id = _member);
        continue when exists (
          select 1 from public.responsibility_reminders x
          where x.responsibility_id = d.responsibility_id and x.member_id = _member and x.task = d.task and x.reminded_on > current_date - 7
        );
        insert into public.notifications (user_id, company_id, title, body, url)
        values (
          _member, _company,
          left(case d.task when 'hours' then 'Odčítať prevádzkové hodiny: ' else 'Skontrolovať case: ' end || d.name, 120),
          left(d.due_count || ' ks – ' || array_to_string(d.items, ', '), 300),
          case d.task when 'hours' then '/equipment' else '/cases' end
        );
        insert into public.responsibility_reminders (responsibility_id, member_id, task, reminded_on)
        values (d.responsibility_id, _member, d.task, current_date)
        on conflict (responsibility_id, member_id, task) do update set reminded_on = excluded.reminded_on;
        _count := _count + 1;
      end loop;
    end loop;
  end loop;
  return _count;
end;
$$;
revoke execute on function public.remind_responsibilities() from public, anon, authenticated;

-- Raz denne ráno (6:00 UTC); bez pg_cron sa pripomienky ukazujú len na Prehľade.
do $$
begin
  create extension if not exists pg_cron;
  perform cron.unschedule(jobid) from cron.job where jobname = 'rigtrack-remind-responsibilities';
  perform cron.schedule('rigtrack-remind-responsibilities', '0 6 * * *', 'select public.remind_responsibilities()');
exception when others then
  raise notice 'pg_cron nie je k dispozícii – pripomienky zodpovedností len na Prehľade';
end;
$$;

-- ===== 0090_notification_center.sql =====
-- RigTrack: zvonček s upozorneniami a viac upozornení (3.10).
-- 1) Upozornenia sa dajú označiť ako prečítané a zmazať (zvonček v appke – aj bez push).
-- 2) Nové upozornenia: zmena termínu / miesta eventu alebo jeho zrušenie (posádke), odmietnutie účasti
--    (tomu, kto event založil), stretávka o hodinu (posádke) a výpožička po termíne (tomu, kto ju založil).
--    Stretávky a výpožičky kontroluje plánovač pg_cron; bez neho sa tieto dve nepošlú.

alter table public.notifications add column if not exists read_at timestamptz;
drop policy if exists notifications_update on public.notifications;
drop policy if exists notifications_delete on public.notifications;
create policy notifications_update on public.notifications for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy notifications_delete on public.notifications for delete to authenticated using (user_id = auth.uid());
grant update (read_at) on public.notifications to authenticated;
grant delete on public.notifications to authenticated;

-- Zmena termínu, miesta alebo zrušenie eventu → všetkým z posádky (okrem tých, čo odmietli).
create or replace function public.notify_event_changed()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  _member uuid;
  _title text;
  _body text;
begin
  if new.status = 'cancelled' and old.status <> 'cancelled' then
    _title := 'Zrušené: ' || new.name;
    _body := to_char(new.starts_on, 'FMDD. FMMM. YYYY');
  elsif new.starts_on <> old.starts_on or new.ends_on <> old.ends_on or new.venue <> old.venue then
    _title := 'Zmena: ' || new.name;
    _body := concat_ws(' · ',
      to_char(new.starts_on, 'FMDD. FMMM. YYYY') || case when new.ends_on > new.starts_on then ' – ' || to_char(new.ends_on, 'FMDD. FMMM. YYYY') else '' end,
      nullif(new.venue, ''));
  else
    return new;
  end if;
  for _member in select distinct c.member_id from public.event_crew c where c.event_id = new.id and c.member_id is not null and c.response <> 'no' loop
    perform public.notify_user(_member, new.company_id, _title, _body, '/events/' || new.id);
  end loop;
  return new;
end;
$$;
revoke execute on function public.notify_event_changed() from public, anon, authenticated;
drop trigger if exists events_notify_changed on public.events;
create trigger events_notify_changed after update of starts_on, ends_on, venue, status on public.events
  for each row execute function public.notify_event_changed();

-- Niekto z posádky odmietol → tomu, kto event založil.
create or replace function public.notify_crew_declined()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  e record;
  _who text;
begin
  if new.response <> 'no' or old.response = 'no' then return new; end if;
  select name, created_by into e from public.events where id = new.event_id;
  if e.created_by is null then return new; end if;
  select coalesce(nullif(full_name, ''), 'Niekto') into _who from public.profiles where id = new.member_id;
  perform public.notify_user(e.created_by, new.company_id, coalesce(_who, 'Niekto') || ' nemôže: ' || e.name, nullif(new.response_note, ''), '/events/' || new.event_id);
  return new;
end;
$$;
revoke execute on function public.notify_crew_declined() from public, anon, authenticated;
drop trigger if exists event_crew_notify_declined on public.event_crew;
create trigger event_crew_notify_declined after update of response on public.event_crew
  for each row execute function public.notify_crew_declined();

-- Stretávka o hodinu a výpožička po termíne (volá plánovač).
alter table public.event_meetings add column if not exists reminded_at timestamptz;
alter table public.loans add column if not exists overdue_notified_on date;

create or replace function public.remind_meetings_and_loans()
returns integer language plpgsql security definer set search_path = '' as $$
declare
  m record;
  l record;
  _member uuid;
  _count integer := 0;
begin
  for m in
    select em.id, em.company_id, em.event_id, em.meet_at, em.address, e.name
    from public.event_meetings em join public.events e on e.id = em.event_id
    where em.reminded_at is null and em.meet_at between now() + interval '15 minutes' and now() + interval '75 minutes' and e.status <> 'cancelled'
  loop
    for _member in select distinct c.member_id from public.event_crew c where c.event_id = m.event_id and c.member_id is not null and c.response <> 'no' loop
      -- Pripomienky plánovača idú aj tomu, kto stretávku zadal (notify_user by vynechal „seba“).
      insert into public.notifications (user_id, company_id, title, body, url)
      values (_member, m.company_id, left('Stretávka o ' || to_char(m.meet_at at time zone 'Europe/Bratislava', 'HH24:MI') || ': ' || m.name, 120), left(m.address, 300), '/events/' || m.event_id);
      _count := _count + 1;
    end loop;
    update public.event_meetings set reminded_at = now() where id = m.id;
  end loop;

  for l in
    select id, company_id, borrower, ends_on, created_by from public.loans
    where status = 'issued' and ends_on < current_date and created_by is not null
      and (overdue_notified_on is null or overdue_notified_on <= current_date - 7)
  loop
    insert into public.notifications (user_id, company_id, title, body, url)
    values (l.created_by, l.company_id, left('Výpožička po termíne: ' || l.borrower, 120), 'Mala sa vrátiť ' || to_char(l.ends_on, 'FMDD. FMMM. YYYY'), '/loans/' || l.id);
    update public.loans set overdue_notified_on = current_date where id = l.id;
    _count := _count + 1;
  end loop;
  return _count;
end;
$$;
revoke execute on function public.remind_meetings_and_loans() from public, anon, authenticated;

do $$
begin
  create extension if not exists pg_cron;
  perform cron.unschedule(jobid) from cron.job where jobname = 'rigtrack-remind-meetings-loans';
  perform cron.schedule('rigtrack-remind-meetings-loans', '*/15 * * * *', 'select public.remind_meetings_and_loans()');
exception when others then
  raise notice 'pg_cron nie je k dispozícii – stretávky a výpožičky sa nepripomínajú';
end;
$$;

-- ===== 0091_cross_company_conflicts.sql =====
-- RigTrack: kolízie naprieč firmami (3.11).
-- Človek môže byť v posádke vo viacerých firmách a jeho vlastná technika môže byť vo viacerých firmách (0085).
-- Firma nevidí eventy inej firmy, preto tieto funkcie vrátia len to, ČI je človek / technika v danom čase
-- obsadená inde (koľko eventov, kusov a od–do) – bez názvov eventov a firiem.

/** Členovia firmy, ktorí sú v termíne v posádke eventu inej firmy (nezrušeného, neodmietnutého). */
create or replace function public.crew_busy_elsewhere(_company_id uuid, _from date, _to date)
returns table (member_id uuid, events integer, starts_on date, ends_on date)
language sql stable security definer set search_path = '' as $$
  select c.member_id, count(distinct e.id)::integer, min(e.starts_on), max(e.ends_on)
  from public.event_crew c
  join public.events e on e.id = c.event_id
  where public.can(_company_id, 'events.view')
    and c.company_id <> _company_id
    and c.member_id in (select m.user_id from public.company_members m where m.company_id = _company_id)
    and c.response <> 'no'
    and e.status <> 'cancelled'
    and e.starts_on <= _to and e.ends_on >= _from
  group by c.member_id;
$$;
revoke execute on function public.crew_busy_elsewhere(uuid, date, date) from public, anon;
grant execute on function public.crew_busy_elsewhere(uuid, date, date) to authenticated;

/** Vlastná technika zdieľaná medzi firmami: koľko kusov je v termíne na eventoch iných firiem. */
create or replace function public.gear_busy_elsewhere(_company_id uuid, _from date, _to date)
returns table (equipment_id uuid, quantity integer, starts_on date, ends_on date)
language sql stable security definer set search_path = '' as $$
  select x.id, sum(ee.quantity)::integer, min(e.starts_on), max(e.ends_on)
  from public.equipment x
  join public.equipment r on coalesce(r.shared_from, r.id) = coalesce(x.shared_from, x.id) and r.company_id <> x.company_id
  join public.event_equipment ee on ee.equipment_id = r.id
  join public.events e on e.id = ee.event_id
  where public.can(_company_id, 'events.view')
    and x.company_id = _company_id
    and (x.shared_from is not null or exists (select 1 from public.equipment c where c.shared_from = x.id))
    and e.status <> 'cancelled'
    and e.starts_on <= _to and e.ends_on >= _from
  group by x.id;
$$;
revoke execute on function public.gear_busy_elsewhere(uuid, date, date) from public, anon;
grant execute on function public.gear_busy_elsewhere(uuid, date, date) to authenticated;

-- ===== 0092_member_rates.sql =====
-- RigTrack: hodinové sadzby a mesačný výkaz dochádzky (3.12).
-- Admin zadá človeku sadzbu za hodinu na firme, doma a na evente; z dochádzky za mesiac appka navrhne odmenu
-- a zapíše ju do Odmien. Sadzbu vidí admin a každý len svoju.

create table if not exists public.member_rates (
  company_id uuid not null references public.companies (id) on delete cascade,
  member_id uuid not null references public.profiles (id) on delete cascade,
  company_rate numeric(8, 2) check (company_rate >= 0),
  home_rate numeric(8, 2) check (home_rate >= 0),
  event_rate numeric(8, 2) check (event_rate >= 0),
  updated_at timestamptz not null default now(),
  primary key (company_id, member_id)
);

alter table public.member_rates enable row level security;
drop policy if exists member_rates_select on public.member_rates;
drop policy if exists member_rates_write on public.member_rates;
create policy member_rates_select on public.member_rates for select to authenticated
  using (public.has_role(company_id, 'admin') or (member_id = auth.uid() and public.is_company_member(company_id)));
create policy member_rates_write on public.member_rates for all to authenticated
  using (public.has_role(company_id, 'admin')) with check (public.has_role(company_id, 'admin') and public.is_member_of(company_id, member_id));
revoke all on public.member_rates from anon, authenticated;
grant select, insert, update, delete on public.member_rates to authenticated;

-- ===== 0093_quotes_auto_sync.sql =====
-- RigTrack: história cenových ponúk a automatické prenášanie zmien vlastnej techniky (3.13).

-- 1) Uložené ponuky: presná kópia ponuky v čase uloženia (riadky, sumy, nastavenia), číslo v rámci roka
--    (2026/1, 2026/2…) a stav (poslaná, prijatá, odmietnutá).
create table if not exists public.event_quotes (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null,
  event_id uuid not null,
  year integer not null default extract(year from now())::integer,
  number integer not null default 0,
  total numeric(12, 2) not null default 0,
  status text not null default 'sent' check (status in ('draft', 'sent', 'accepted', 'rejected')),
  data jsonb not null default '{}' check (jsonb_typeof(data) = 'object' and char_length(data::text) <= 200000),
  note text not null default '' check (char_length(note) <= 500),
  created_by uuid default auth.uid() references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  foreign key (company_id, event_id) references public.events (company_id, id) on delete cascade
);
create index if not exists event_quotes_event_idx on public.event_quotes (company_id, event_id, created_at desc);
create unique index if not exists event_quotes_number_idx on public.event_quotes (company_id, year, number);

-- Číslo ponuky pridelí databáza: najvyššie v roku + 1.
create or replace function public.event_quotes_number()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  perform pg_advisory_xact_lock(hashtext('event_quotes:' || new.company_id::text || ':' || new.year::text));
  select coalesce(max(number), 0) + 1 into new.number from public.event_quotes where company_id = new.company_id and year = new.year;
  return new;
end;
$$;
revoke execute on function public.event_quotes_number() from public, anon, authenticated;
drop trigger if exists event_quotes_number on public.event_quotes;
create trigger event_quotes_number before insert on public.event_quotes for each row execute function public.event_quotes_number();

alter table public.event_quotes enable row level security;
drop policy if exists event_quotes_select on public.event_quotes;
drop policy if exists event_quotes_insert on public.event_quotes;
drop policy if exists event_quotes_update on public.event_quotes;
drop policy if exists event_quotes_delete on public.event_quotes;
create policy event_quotes_select on public.event_quotes for select to authenticated using (public.can(company_id, 'events.view'));
create policy event_quotes_insert on public.event_quotes for insert to authenticated with check (public.can(company_id, 'events.edit'));
create policy event_quotes_update on public.event_quotes for update to authenticated using (public.can(company_id, 'events.edit')) with check (public.can(company_id, 'events.edit'));
create policy event_quotes_delete on public.event_quotes for delete to authenticated using (public.can(company_id, 'events.edit'));
revoke all on public.event_quotes from anon, authenticated;
grant select, insert, delete on public.event_quotes to authenticated;
grant update (status, note) on public.event_quotes to authenticated;

-- 2) Vlastná technika vo viacerých firmách (0085): zmena pôvodnej položky sa do kópií prenesie sama
--    (doteraz tlačidlom „Aktualizovať kópie“).
create or replace function public.equipment_sync_copies()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.shared_from is not null then return new; end if;
  update public.equipment c
    set name = new.name, kind = new.kind, attributes = new.attributes, manufacturer = new.manufacturer, model = new.model,
        serial_number = new.serial_number, quantity = new.quantity, track_units = new.track_units, unit_ids = new.unit_ids, note = new.note
    where c.shared_from = new.id
      and (c.name, c.kind, c.attributes, c.manufacturer, c.model, c.serial_number, c.quantity, c.track_units, c.unit_ids, c.note)
          is distinct from (new.name, new.kind, new.attributes, new.manufacturer, new.model, new.serial_number, new.quantity, new.track_units, new.unit_ids, new.note);
  return new;
end;
$$;
revoke execute on function public.equipment_sync_copies() from public, anon, authenticated;
drop trigger if exists equipment_sync_copies on public.equipment;
create trigger equipment_sync_copies after update of name, kind, attributes, manufacturer, model, serial_number, quantity, track_units, unit_ids, note on public.equipment
  for each row when (new.shared_from is null) execute function public.equipment_sync_copies();

-- ===== 0094_company_creation_approval.sql =====
-- RigTrack: zakladanie nových firiem len s povolením (3.14).
-- Novú firmu smie založiť vývojár aplikácie (app_developers) alebo človek, ktorému to vývojár povolil.
-- Ostatní pošlú žiadosť; vývojár ju v appke schváli (povolí zakladanie) alebo zamietne a človeku príde upozornenie.
-- Kým nie je zapísaný žiadny vývojár, zakladať môže každý (nová inštalácia sa nezamkne).
-- Demo firma a firma založená partnerovi (Firmy a kontakty) sa tým neobmedzujú.

create table if not exists public.company_creators (
  user_id uuid primary key references public.profiles (id) on delete cascade,
  granted_by uuid references public.profiles (id) on delete set null,
  granted_at timestamptz not null default now()
);
alter table public.company_creators enable row level security;
drop policy if exists company_creators_select on public.company_creators;
drop policy if exists company_creators_write on public.company_creators;
create policy company_creators_select on public.company_creators for select to authenticated using (user_id = auth.uid() or public.is_developer());
create policy company_creators_write on public.company_creators for all to authenticated using (public.is_developer()) with check (public.is_developer());
revoke all on public.company_creators from anon, authenticated;
grant select, insert, delete on public.company_creators to authenticated;

create table if not exists public.company_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  company_name text not null check (char_length(trim(company_name)) between 1 and 120),
  note text not null default '' check (char_length(note) <= 500),
  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists company_requests_status_idx on public.company_requests (status, created_at desc);
alter table public.company_requests enable row level security;
drop policy if exists company_requests_select on public.company_requests;
drop policy if exists company_requests_insert on public.company_requests;
drop policy if exists company_requests_delete on public.company_requests;
create policy company_requests_select on public.company_requests for select to authenticated using (user_id = auth.uid() or public.is_developer());
create policy company_requests_insert on public.company_requests for insert to authenticated with check (user_id = auth.uid());
create policy company_requests_delete on public.company_requests for delete to authenticated using (user_id = auth.uid() or public.is_developer());
revoke all on public.company_requests from anon, authenticated;
grant select, insert, delete on public.company_requests to authenticated;

/** Smie prihlásený zakladať firmy? */
create or replace function public.can_create_company()
returns boolean language sql stable security definer set search_path = '' as $$
  select auth.uid() is not null and (
    not exists (select 1 from public.app_developers)
    or public.is_developer()
    or exists (select 1 from public.company_creators c where c.user_id = auth.uid())
  );
$$;
revoke execute on function public.can_create_company() from public, anon;
grant execute on function public.can_create_company() to authenticated;

create or replace function public.create_company(_name text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if not public.can_create_company() then
    raise exception 'Založenie novej firmy musí povoliť správca aplikácie' using errcode = 'insufficient_privilege';
  end if;
  insert into public.companies (name, created_by) values (trim(_name), auth.uid()) returning id into _id;
  insert into public.company_members (company_id, user_id, role) values (_id, auth.uid(), 'admin');
  return _id;
end;
$$;

/** Vývojár rozhodne o žiadosti: schválenie povolí človeku zakladať firmy. Človeku príde upozornenie. */
create or replace function public.decide_company_request(_request_id uuid, _approve boolean)
returns void language plpgsql security definer set search_path = '' as $$
declare
  r public.company_requests%rowtype;
begin
  if not public.is_developer() then
    raise exception 'Len vývojár aplikácie' using errcode = 'insufficient_privilege';
  end if;
  select * into r from public.company_requests where id = _request_id;
  if not found then return; end if;
  update public.company_requests set status = case when _approve then 'approved' else 'rejected' end, decided_at = now() where id = _request_id;
  if _approve then
    insert into public.company_creators (user_id, granted_by) values (r.user_id, auth.uid()) on conflict (user_id) do nothing;
  end if;
  insert into public.notifications (user_id, title, body, url)
  values (
    r.user_id,
    case when _approve then 'Môžete založiť firmu' else 'Žiadosť o firmu zamietnutá' end,
    left(case when _approve then 'Založte ju na „Vyberte firmu“ → Vytvoriť novú firmu: ' else 'Firma: ' end || r.company_name, 300),
    case when _approve then '/company/create' else '/company/select' end
  );
end;
$$;
revoke execute on function public.decide_company_request(uuid, boolean) from public, anon;
grant execute on function public.decide_company_request(uuid, boolean) to authenticated;

/** Žiadosti pre vývojára aj s menom a e-mailom žiadateľa. */
create or replace function public.pending_company_requests()
returns table (id uuid, user_id uuid, full_name text, email text, company_name text, note text, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select r.id, r.user_id, coalesce(p.full_name, ''), coalesce(u.email, ''), r.company_name, r.note, r.created_at
  from public.company_requests r
  left join public.profiles p on p.id = r.user_id
  left join auth.users u on u.id = r.user_id
  where public.is_developer() and r.status = 'pending'
  order by r.created_at;
$$;
revoke execute on function public.pending_company_requests() from public, anon;
grant execute on function public.pending_company_requests() to authenticated;

-- Žiadosť o firmu pošle upozornenie všetkým vývojárom.
create or replace function public.notify_company_request()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.notifications (user_id, title, body, url)
  select d.user_id, left('Žiadosť o novú firmu: ' || new.company_name, 120), left(new.note, 300), '/settings?tab=developer'
  from public.app_developers d where d.user_id <> new.user_id;
  return new;
end;
$$;
revoke execute on function public.notify_company_request() from public, anon, authenticated;
drop trigger if exists company_requests_notify on public.company_requests;
create trigger company_requests_notify after insert on public.company_requests for each row execute function public.notify_company_request();

-- ===== 0095_event_stage_plans.sql =====
-- RigTrack: plán pódia Nivtec uložený k eventu (3.15).
-- Kalkulačka uloží zadanie (rozmery, výška, schody, plachta, molo, rizery…) k eventu; pri otvorení z eventu
-- sa plán načíta a v detaile eventu je súhrn s odkazom na nákres a tlač.

create table if not exists public.event_stage_plans (
  company_id uuid not null,
