-- Wi-Fi: k technike (router v racku) alebo sieť firmy (sídlo, kancelária, sklad).
alter table public.wifi_networks add column if not exists scope text not null default 'equipment' check (scope in ('equipment', 'company'));

drop policy if exists wifi_networks_select on public.wifi_networks;
create policy wifi_networks_select on public.wifi_networks for select to authenticated
  using (public.can(company_id, 'networks.view'));

-- Heslo nie je v bežnom čítaní tabuľky; dostane ho len ten, kto smie heslá vidieť.
revoke select on public.wifi_networks from authenticated;
grant select (id, company_id, ssid, security, hidden, subnet, router_ip, management_ip, router_model, dhcp, dhcp_start, dhcp_end, equipment_id, place, note, created_at, scope)
  on public.wifi_networks to authenticated;
grant update (scope) on public.wifi_networks to authenticated;

create or replace function public.wifi_passwords(_company_id uuid)
returns table (id uuid, password text) language sql stable security definer set search_path = '' as $$
  select n.id, n.password from public.wifi_networks n
  where n.company_id = _company_id and public.can(_company_id, 'networks.passwords');
$$;
revoke execute on function public.wifi_passwords(uuid) from public, anon;
grant execute on function public.wifi_passwords(uuid) to authenticated;

drop policy if exists wifi_router_logins_all on public.wifi_router_logins;
create policy wifi_router_logins_all on public.wifi_router_logins for all to authenticated
  using (public.can(company_id, 'networks.admin'))
  with check (
    public.can(company_id, 'networks.admin')
    and exists (select 1 from public.wifi_networks n where n.id = network_id and n.company_id = wifi_router_logins.company_id)
  );

-- ===== 0104_patch_templates_dmx.sql =====
-- RigTrack 4.4: šablóny patch listov (zvuk aj DMX) a DMX patch list pri evente.

-- Šablóna = pomenovaný zoznam riadkov (napr. „Kapela – základ“), ktorý sa pri evente načíta jedným klikom.
create table if not exists public.patch_templates (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id) on delete cascade,
  kind text not null check (kind in ('sound', 'dmx')),
  name text not null check (char_length(trim(name)) between 1 and 80),
  note text not null default '' check (char_length(note) <= 300),
  lines jsonb not null default '[]' check (jsonb_typeof(lines) = 'array' and jsonb_array_length(lines) <= 512),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists patch_templates_company_idx on public.patch_templates (company_id, kind, name);
alter table public.patch_templates enable row level security;
drop policy if exists patch_templates_select on public.patch_templates;
drop policy if exists patch_templates_write on public.patch_templates;
create policy patch_templates_select on public.patch_templates for select to authenticated using (public.can(company_id, 'events.view'));
create policy patch_templates_write on public.patch_templates for all to authenticated
  using (public.can(company_id, 'events.edit')) with check (public.can(company_id, 'events.edit'));
revoke all on public.patch_templates from anon, authenticated;
grant select, insert, delete on public.patch_templates to authenticated;
grant update (name, note, lines, updated_at) on public.patch_templates to authenticated;

-- DMX patch list eventu: jedno svetlo (alebo kus) na riadok – linka, adresa, počet kanálov, mód.
create table if not exists public.event_dmx_patch (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null,
  event_id uuid not null,
  universe text not null default '' check (char_length(universe) <= 20),
  address integer check (address between 1 and 512),
  channels integer not null default 1 check (channels between 1 and 512),
  name text not null default '' check (char_length(name) <= 80),
  equipment_id uuid references public.equipment (id) on delete set null,
  unit integer check (unit between 1 and 100000),
  mode text not null default '' check (char_length(mode) <= 40),
  note text not null default '' check (char_length(note) <= 200),
  foreign key (company_id, event_id) references public.events (company_id, id) on delete cascade
);
create index if not exists event_dmx_patch_event_idx on public.event_dmx_patch (event_id, universe, address);
alter table public.event_dmx_patch enable row level security;
drop policy if exists event_dmx_patch_select on public.event_dmx_patch;
drop policy if exists event_dmx_patch_write on public.event_dmx_patch;
create policy event_dmx_patch_select on public.event_dmx_patch for select to authenticated using (public.can(company_id, 'events.view'));
create policy event_dmx_patch_write on public.event_dmx_patch for all to authenticated
  using (public.can(company_id, 'events.edit')) with check (public.can(company_id, 'events.edit'));
revoke all on public.event_dmx_patch from anon, authenticated;
grant select, insert, delete on public.event_dmx_patch to authenticated;
grant update (universe, address, channels, name, equipment_id, unit, mode, note) on public.event_dmx_patch to authenticated;

-- ===== 0105_public_scan.sql =====
-- RigTrack 4.6: QR štítok pre človeka bez účtu – „Našli ste techniku firmy X, kontakt…“.
-- Predvolene vypnuté; zapína admin v Nastaveniach → Firma. Ukáže sa len názov veci a kontakt firmy.

alter table public.company_profile add column if not exists public_scan boolean not null default false;
grant update (public_scan) on public.company_profile to authenticated;

create or replace function public.public_scan_info(_kind text, _id uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  _company uuid;
  _name text;
  p public.company_profile%rowtype;
begin
  if _kind = 'equipment' then
    select company_id, name into _company, _name from public.equipment where id = _id and deleted_at is null;
  elsif _kind = 'case' then
    select company_id, name into _company, _name from public.cases where id = _id and deleted_at is null;
  end if;
  if _company is null then
    return null;
  end if;
  select * into p from public.company_profile where company_id = _company;
  if not found or not p.public_scan then
    return jsonb_build_object('enabled', false);
  end if;
  return jsonb_build_object(
    'enabled', true,
    'name', _name,
    'company', coalesce(nullif(p.legal_name, ''), (select name from public.companies where id = _company)),
    'phone', p.phone,
    'email', p.email,
    'web', p.web
  );
end;
$$;
revoke execute on function public.public_scan_info(text, uuid) from public;
grant execute on function public.public_scan_info(text, uuid) to anon, authenticated;

-- ===== 0106_demo_v46.sql =====
-- RigTrack 4.6: demo firma s novinkami od 4.0 – DMX adresy kusov (linka, adresa, mód), príkon a váha svetiel,
-- zvukový aj DMX patch list na festivale, šablóny patch listov, občianske združenie medzi firmami, „Našli ste…“.
-- Nové demo ich dostane hneď; existujúce demo firmy sa doplnia raz (ak ešte nemajú šablónu „Kapela – základ“).

create or replace function public.seed_demo_v46(_company uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  _event uuid;
  e record;
  _info jsonb;
  _unit integer;
begin
  if exists (select 1 from public.patch_templates where company_id = _company and name = 'Kapela – základ') then
    return;
  end if;
  select id into _event from public.events where company_id = _company and name = 'Letný festival';

  -- Svetlá Beam 230: DMX módy, príkon, váha a pri každom kuse linka 1, adresy za sebou po 16 kanáloch
  for e in select id, unit_ids from public.equipment where company_id = _company and name = 'Beam 230' and deleted_at is null loop
    _info := '{}'::jsonb;
    foreach _unit in array e.unit_ids loop
      _info := _info || jsonb_build_object(_unit::text, jsonb_build_object('dmxLine', '1', 'dmxAddress', (_unit - 1) * 16 + 1, 'dmxMode', 'Basic'));
    end loop;
    update public.equipment
      set unit_info = _info,
          attributes = attributes || '{"dmxModes": [{"name": "Basic", "channels": 16}, {"name": "Extended", "channels": 24}], "powerW": 330, "weightKg": 18}'
      where id = e.id;
  end loop;

  -- Šablóny patch listov
  insert into public.patch_templates (company_id, kind, name, note, lines) values
    (_company, 'sound', 'Kapela – základ', 'bicie, basa, 2 gitary, klávesy, 2 spevy', '[
      {"channel": 1, "name": "Kick", "stagebox": "SB1", "stageboxInput": 1, "source": "mic", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "short", "phantom": false, "note": ""},
      {"channel": 2, "name": "Snare", "stagebox": "SB1", "stageboxInput": 2, "source": "mic", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "clamp", "phantom": false, "note": ""},
      {"channel": 3, "name": "Overhead L", "stagebox": "SB1", "stageboxInput": 3, "source": "mic", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "tall", "phantom": true, "note": ""},
      {"channel": 4, "name": "Overhead R", "stagebox": "SB1", "stageboxInput": 4, "source": "mic", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "tall", "phantom": true, "note": ""},
      {"channel": 5, "name": "Basa DI", "stagebox": "SB1", "stageboxInput": 5, "source": "di", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "", "phantom": true, "note": ""},
      {"channel": 6, "name": "Gitara 1", "stagebox": "SB1", "stageboxInput": 6, "source": "mic", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "short", "phantom": false, "note": ""},
      {"channel": 7, "name": "Gitara 2", "stagebox": "SB1", "stageboxInput": 7, "source": "mic", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "short", "phantom": false, "note": ""},
      {"channel": 8, "name": "Klávesy L", "stagebox": "SB1", "stageboxInput": 8, "source": "di", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "", "phantom": true, "note": ""},
      {"channel": 9, "name": "Klávesy R", "stagebox": "SB1", "stageboxInput": 9, "source": "di", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "", "phantom": true, "note": ""},
      {"channel": 10, "name": "Spev 1", "stagebox": "SB1", "stageboxInput": 10, "source": "wireless", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "tall", "phantom": false, "note": ""},
      {"channel": 11, "name": "Spev 2", "stagebox": "SB1", "stageboxInput": 11, "source": "mic", "equipmentId": null, "capsuleId": null, "connector": "", "stand": "tall", "phantom": false, "note": ""}
    ]'::jsonb),
    (_company, 'dmx', 'Stage – 8 beamov', 'linka 1, Basic 16 ch', (
      select jsonb_agg(jsonb_build_object('universe', '1', 'address', (n - 1) * 16 + 1, 'channels', 16, 'name', 'Beam 230 #' || n, 'equipmentId', null, 'unit', n, 'mode', 'Basic', 'note', '') order by n)
      from generate_series(1, 8) n
    ));

  -- Patch listy na festivale: zvuk zo šablóny a DMX z beamov
  if _event is not null then
    insert into public.event_patch (company_id, event_id, channel, name, stagebox, stagebox_input, source, stand, phantom)
    select _company, _event, (l ->> 'channel')::int, l ->> 'name', l ->> 'stagebox', (l ->> 'stageboxInput')::int, l ->> 'source', l ->> 'stand', (l ->> 'phantom')::boolean
    from public.patch_templates t, jsonb_array_elements(t.lines) l
    where t.company_id = _company and t.name = 'Kapela – základ'
    on conflict do nothing;
    insert into public.event_dmx_patch (company_id, event_id, universe, address, channels, name, mode)
    select _company, _event, '1', (n - 1) * 16 + 1, 16, 'Beam 230 #' || n, 'Basic' from generate_series(1, 8) n;
  end if;

  -- Občianske združenie medzi firmami a kontaktmi
  insert into public.partners (company_id, name, legal_name, ico, address, ceo, legal_form, note)
  values (_company, 'OZ Kultúra mesta', 'Občianske združenie Kultúra mesta', '12345678', 'Hlavná 1, Mesto', 'Mária Predsedová', 'oz', 'Organizátor letných podujatí');

  -- „Našli ste…“ pri QR štítkoch zapnuté (ukážka)
  insert into public.company_profile (company_id, phone, email, public_scan)
  values (_company, '+421 900 000 001', 'demo@rigtrack.sk', true)
  on conflict (company_id) do update set public_scan = true;
end;
$$;
revoke execute on function public.seed_demo_v46(uuid) from public, anon, authenticated;

create or replace function public.create_demo_company()
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select id into _id from public.companies where demo_owner = auth.uid();
  if _id is not null then
    return _id;
  end if;
  insert into public.companies (name, created_by, demo_owner) values ('DEMO – Ukážková firma', auth.uid(), auth.uid()) returning id into _id;
  insert into public.company_members (company_id, user_id, role) values (_id, auth.uid(), 'admin');
  perform public.seed_demo_company(_id);
  perform public.seed_demo_extras(_id, auth.uid());
  perform public.seed_demo_v4(_id, auth.uid());
  perform public.seed_demo_v46(_id);
  return _id;
end;
$$;

do $$
declare
  c record;
begin
  for c in select id from public.companies where demo_owner is not null loop
    begin
      perform public.seed_demo_v46(c.id);
    exception when others then
      raise notice 'Demo % sa nepodarilo doplniť: %', c.id, sqlerrm;
    end;
  end loop;
end;
$$;

-- ===== 0107_address_privacy.sql =====
-- RigTrack 4.8: IP a MAC adresy stráži databáza (oprávnenie networks.addresses), nielen appka.
-- • technika: IP a MAC sú v tabuľke equipment_addresses (čítať len s oprávnením)
-- • Wi-Fi: IP rozsah, gateway, IP správy a DHCP rozsah tiež len cez network_addresses()
-- • zariadenia hostí: len s „Vidieť IP a MAC adresy“
-- POZOR pre ďalšie migrácie: wifi_networks má právo čítať po stĺpcoch – nový stĺpec treba sprístupniť
-- (grant select (stĺpec) on public.wifi_networks to authenticated).

-- Technika: IP a MAC sa presúvajú do vlastnej tabuľky s prístupom podľa oprávnenia.
-- (Stĺpce v equipment ostávajú kvôli starším funkciám, ale sú prázdne.)
create table if not exists public.equipment_addresses (
  equipment_id uuid primary key references public.equipment (id) on delete cascade,
  company_id uuid not null references public.companies (id) on delete cascade,
  ip text not null default '' check (char_length(ip) <= 64),
  mac text not null default '' check (char_length(mac) <= 32)
);
alter table public.equipment_addresses enable row level security;
drop policy if exists equipment_addresses_select on public.equipment_addresses;
drop policy if exists equipment_addresses_write on public.equipment_addresses;
create policy equipment_addresses_select on public.equipment_addresses for select to authenticated using (public.can(company_id, 'networks.addresses'));
create policy equipment_addresses_write on public.equipment_addresses for all to authenticated
  using (public.can(company_id, 'equipment.edit') and public.can(company_id, 'networks.addresses'))
  with check (
    public.can(company_id, 'equipment.edit') and public.can(company_id, 'networks.addresses')
    and exists (select 1 from public.equipment e where e.id = equipment_id and e.company_id = equipment_addresses.company_id)
  );
revoke all on public.equipment_addresses from anon, authenticated;
grant select, insert, delete on public.equipment_addresses to authenticated;
grant update (ip, mac) on public.equipment_addresses to authenticated;

insert into public.equipment_addresses (equipment_id, company_id, ip, mac)
select id, company_id, ip_address, mac_address from public.equipment where ip_address <> '' or mac_address <> ''
on conflict (equipment_id) do nothing;
update public.equipment set ip_address = '', mac_address = '' where ip_address <> '' or mac_address <> '';

-- Kto zapíše IP / MAC priamo do techniky (staršia appka, import), tomu sa presunú do equipment_addresses.
-- Prázdne hodnoty uložené adresy nemažú (človek bez oprávnenia ich pri úprave nevidí a nesmie ich zmazať).
create or replace function public.equipment_move_addresses()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  insert into public.equipment_addresses (equipment_id, company_id, ip, mac)
  values (new.id, new.company_id, coalesce(new.ip_address, ''), coalesce(new.mac_address, ''))
  on conflict (equipment_id) do update
    set ip = case when excluded.ip <> '' then excluded.ip else public.equipment_addresses.ip end,
        mac = case when excluded.mac <> '' then excluded.mac else public.equipment_addresses.mac end;
  update public.equipment set ip_address = '', mac_address = '' where id = new.id;
  return null;
end;
$$;
drop trigger if exists equipment_move_addresses on public.equipment;
create trigger equipment_move_addresses after insert or update of ip_address, mac_address on public.equipment
  for each row when (new.ip_address <> '' or new.mac_address <> '') execute function public.equipment_move_addresses();

-- Wi-Fi: bez hesla (0103) a bez adries.
do $$
declare
  _columns text;
begin
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into _columns
  from information_schema.columns
  where table_schema = 'public' and table_name = 'wifi_networks'
    and column_name not in ('password', 'subnet', 'router_ip', 'management_ip', 'dhcp_start', 'dhcp_end');
  execute 'revoke select on public.wifi_networks from authenticated';
  execute format('grant select (%s) on public.wifi_networks to authenticated', _columns);
end;
$$;

/** Adresy Wi-Fi sietí firmy (IP rozsah, gateway, DHCP) – len s oprávnením „Vidieť IP a MAC adresy“. */
create or replace function public.network_addresses(_company_id uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select case when public.can(_company_id, 'networks.addresses') then jsonb_build_object(
    'allowed', true,
    'wifi', coalesce((
      select jsonb_agg(jsonb_build_object('id', n.id, 'subnet', n.subnet, 'routerIp', n.router_ip, 'managementIp', n.management_ip, 'dhcpStart', n.dhcp_start, 'dhcpEnd', n.dhcp_end))
      from public.wifi_networks n where n.company_id = _company_id
    ), '[]'::jsonb)
  ) else jsonb_build_object('allowed', false, 'wifi', '[]'::jsonb) end;
$$;
revoke execute on function public.network_addresses(uuid) from public, anon;
grant execute on function public.network_addresses(uuid) to authenticated;

/** Ktoré stĺpce tabuľky smie prihlásený čítať (záloha číta len tie). */
create or replace function public.readable_columns(_table text)
returns text[] language sql stable set search_path = '' as $$
  select coalesce(array_agg(c.column_name::text order by c.ordinal_position), '{}')
  from information_schema.columns c
  where c.table_schema = 'public' and c.table_name = _table
    and has_column_privilege('public.' || quote_ident(_table), c.column_name, 'select');
$$;
grant execute on function public.readable_columns(text) to authenticated;

-- Zariadenia hostí: len s „Vidieť IP a MAC adresy“ (zariadenia členov ostávajú: svoje a „Spravovať tím“).
drop policy if exists guest_devices_select on public.guest_devices;
create policy guest_devices_select on public.guest_devices for select to authenticated using (public.can(company_id, 'networks.addresses'));

-- ===== 0108_pack_units.sql =====
-- RigTrack 4.8: pack list – naskenované jednotlivé kusy (QR kusu „Beam 7R #7“). Keď sú naskenované všetky kusy
-- položky, appka položku odškrtne. Kto smie odškrtávať, smie aj skenovať kusy (rovnako ako event_pack_checks).

create table if not exists public.event_pack_units (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null,
  event_id uuid not null,
  equipment_id uuid not null references public.equipment (id) on delete cascade,
  unit integer not null check (unit between 1 and 100000),
  phase text not null check (phase in ('out', 'back')),
  checked_by uuid default auth.uid() references public.profiles (id) on delete set null,
  checked_at timestamptz not null default now(),
  unique (event_id, equipment_id, unit, phase),
  foreign key (company_id, event_id) references public.events (company_id, id) on delete cascade
);
alter table public.event_pack_units enable row level security;
drop policy if exists event_pack_units_select on public.event_pack_units;
drop policy if exists event_pack_units_write on public.event_pack_units;
create policy event_pack_units_select on public.event_pack_units for select to authenticated using (public.can(company_id, 'events.view'));
create policy event_pack_units_write on public.event_pack_units for all to authenticated
  using (
    public.can(company_id, 'events.edit')
    or exists (select 1 from public.event_crew c where c.event_id = event_pack_units.event_id and c.member_id = auth.uid())
  )
  with check (
    public.can(company_id, 'events.edit')
    or exists (select 1 from public.event_crew c where c.event_id = event_pack_units.event_id and c.member_id = auth.uid())
  );
revoke all on public.event_pack_units from anon, authenticated;
grant select, insert, delete on public.event_pack_units to authenticated;

-- ===== 0109_case_bags.sql =====
-- RigTrack 4.9: pri cases aj taška (napr. taška na stojany) – vedľa case a racku.
alter table public.cases drop constraint if exists cases_kind_check;
alter table public.cases add constraint cases_kind_check check (kind in ('case', 'rack', 'bag'));

-- ===== 0110_merge_equipment.sql =====
-- RigTrack 4.11: spojenie rozdelenej techniky späť (napr. omylom 2 ks do case a potom von → 2 + 8 = 10 ks).
-- Odkazy na zlúčenú časť (eventy, výpožičky, servis, hodiny…) sa presunú na tú, do ktorej sa spája.

/** Spojí časť `_from` do `_into` (tá istá technika, obe mimo case alebo v tom istom case). */
create or replace function public.merge_equipment(_from uuid, _into uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  a public.equipment%rowtype;
  b public.equipment%rowtype;
  fk record;
begin
  select * into a from public.equipment where id = _from and deleted_at is null;
  select * into b from public.equipment where id = _into and deleted_at is null;
  if a.id is null or b.id is null or a.id = b.id or a.company_id <> b.company_id or not public.can(a.company_id, 'equipment.edit') then
    raise exception 'Túto techniku nemôžete spojiť' using errcode = 'insufficient_privilege';
  end if;
  if lower(trim(a.name)) <> lower(trim(b.name)) or a.kind <> b.kind or a.case_id is distinct from b.case_id then
    raise exception 'Spojiť sa dá len tá istá technika na tom istom mieste (obe mimo case alebo v tom istom case)' using errcode = 'check_violation';
  end if;

  -- Všetky odkazy na zlučovanú časť presunúť (okrem odkazov techniky na seba, napr. kópia / zdieľanie).
  for fk in
    -- Aj zložené odkazy (company_id, equipment_id): berie sa stĺpec, ktorý ukazuje na equipment.id.
    select distinct cl.relname as tbl, att.attname as col
    from pg_constraint con
    join pg_class cl on cl.oid = con.conrelid
    join pg_namespace ns on ns.oid = cl.relnamespace
    cross join lateral unnest(con.conkey, con.confkey) as k(own, ref)
    join pg_attribute att on att.attrelid = con.conrelid and att.attnum = k.own
    join pg_attribute target on target.attrelid = con.confrelid and target.attnum = k.ref and target.attname = 'id'
    where con.contype = 'f' and con.confrelid = 'public.equipment'::regclass and ns.nspname = 'public'
      and cl.relname not in ('equipment', 'equipment_addresses')
  loop
    begin
      execute format('update public.%I set %I = $1 where %I = $2', fk.tbl, fk.col, fk.col) using _into, _from;
    exception when unique_violation then
      raise exception 'Obe časti sú na tom istom evente alebo výpožičke (%) – najprv ju tam upravte.', fk.tbl using errcode = 'check_violation';
    end;
  end loop;

  -- Kusy a čísla kusov.
  if b.track_units or a.track_units then
    update public.equipment
      set track_units = true,
          unit_ids = array(
            select distinct u from unnest(
              (case when cardinality(b.unit_ids) > 0 then b.unit_ids else array(select generate_series(1, b.quantity)) end)
              || (case when cardinality(a.unit_ids) > 0 then a.unit_ids else array(select generate_series(1, a.quantity)) end)
            ) u order by u),
          quantity = b.quantity + a.quantity,
          unit_info = coalesce(b.unit_info, '{}'::jsonb) || coalesce(a.unit_info, '{}'::jsonb)
      where id = b.id;
  else
    update public.equipment set quantity = b.quantity + a.quantity where id = b.id;
  end if;
  delete from public.equipment where id = a.id;
  return b.id;
end;
$$;
revoke execute on function public.merge_equipment(uuid, uuid) from public, anon;
grant execute on function public.merge_equipment(uuid, uuid) to authenticated;

/**
 * Vybrať z case: technika ide von z case a ak je tá istá technika už mimo case, spojí sa s ňou.
 * Vráti id výsledného riadku.
 */
create or replace function public.take_out_of_case(_id uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  e public.equipment%rowtype;
  _sibling uuid;
begin
  select * into e from public.equipment where id = _id and deleted_at is null;
  if e.id is null or not public.can(e.company_id, 'equipment.edit') then
    raise exception 'Túto techniku nemôžete meniť' using errcode = 'insufficient_privilege';
  end if;
  update public.equipment set case_id = null, label_role = null where id = e.id;
  select id into _sibling from public.equipment
    where company_id = e.company_id and id <> e.id and deleted_at is null and case_id is null
      and lower(trim(name)) = lower(trim(e.name)) and kind = e.kind
      and coalesce(manufacturer, '') = coalesce(e.manufacturer, '') and coalesce(model, '') = coalesce(e.model, '')
      and owner_staff_id is not distinct from e.owner_staff_id
    order by quantity desc
    limit 1;
  if _sibling is null then
    return e.id;
  end if;
  begin
    return public.merge_equipment(e.id, _sibling);
  exception when check_violation then
    -- Nedá sa spojiť (napr. obe na tom istom evente) – ostane samostatne mimo case.
    return e.id;
  end;
end;
$$;
revoke execute on function public.take_out_of_case(uuid) from public, anon;
grant execute on function public.take_out_of_case(uuid) to authenticated;

-- ===== 0111_demo_invitations.sql =====
-- RigTrack 4.13: pozvánka len do dema. Vývojár pozve e-mail, ktorý sa smie zaregistrovať,
-- ale nedostane prístup do žiadnej firmy – po prihlásení si otvorí vlastnú demo firmu.

create table if not exists public.demo_invitations (
  email text primary key check (email = lower(trim(email)) and email like '%_@_%'),
  note text not null default '' check (char_length(note) <= 200),
  invited_by uuid default auth.uid() references auth.users (id) on delete set null,
  created_at timestamptz not null default now()
);

alter table public.demo_invitations enable row level security;
revoke all on public.demo_invitations from anon, authenticated;
grant select, insert, delete on public.demo_invitations to authenticated;

drop policy if exists demo_invitations_developer on public.demo_invitations;
create policy demo_invitations_developer on public.demo_invitations
  for all to authenticated using (public.is_developer()) with check (public.is_developer());

-- Registrácia: pozvánka do firmy alebo do dema.
create or replace function public.hook_require_invitation(event jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  _email text := lower(trim(coalesce(event -> 'user' ->> 'email', '')));
begin
  if _email <> '' and (
    exists (select 1 from public.company_invitations i where i.email = _email)
    or exists (select 1 from public.demo_invitations d where d.email = _email)
  ) then
    return '{}'::jsonb;
  end if;
  return jsonb_build_object('error', jsonb_build_object('http_code', 403, 'message', 'Registrácia je len na pozvánku.'));
end;
$$;

revoke execute on function public.hook_require_invitation(jsonb) from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'supabase_auth_admin') then
    grant execute on function public.hook_require_invitation(jsonb) to supabase_auth_admin;
  end if;
end;
$$;

-- ===== 0112_demo_invitation_status.sql =====
-- RigTrack 4.14: vývojár vidí pri pozvánkach do dema, či sa človek zaregistroval, kedy sa naposledy
-- prihlásil a či si založil demo firmu.

create or replace function public.demo_invitation_status()
returns table (email text, note text, invited_at timestamptz, registered boolean, last_sign_in_at timestamptz, demo_created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select d.email, d.note, d.created_at, u.id is not null, u.last_sign_in_at, c.created_at
  from public.demo_invitations d
  left join lateral (select id, last_sign_in_at from auth.users where lower(auth.users.email) = d.email limit 1) u on true
  left join lateral (select created_at from public.companies where demo_owner = u.id limit 1) c on true
  where public.is_developer()
  order by d.created_at desc
$$;

revoke execute on function public.demo_invitation_status() from public, anon;
grant execute on function public.demo_invitation_status() to authenticated;

-- ===== 0113_cable_color_types.sql =====
-- RigTrack 4.15: farby dĺžok káblov zvlášť pre typ kábla – XLR / DMX, powerCON, 230 V.
-- Prázdny typ ('') = ostatné káble; doterajšie farby ostávajú tam a platia, kým typ nemá vlastnú.

alter table public.cable_colors add column if not exists cable_type text not null default '';

do $$
begin
  alter table public.cable_colors drop constraint if exists cable_colors_cable_type_check;
