-- ===== 0142_demo_v7.sql =====
-- RigTrack 7.13: demo firma doplnená o novinky 6.x–7.x – plán skladu (regály s policami a paletami, palety na zemi,
-- hliník, miestnosť, dvere, okno, stĺp), cases uložené na regáloch a paletách, hliník (trussy) uložený v stohoch,
-- činnosti pred / po evente s vlastníkmi a bezdrôtový systém s vysielačmi. Vymyslené údaje; spustí sa raz na firmu.

create or replace function public.seed_demo_v7(_company uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  _rack_a uuid;
  _rack_b uuid;
  _pallet uuid;
  _bays jsonb := '[{"widthCm": 267, "levels": [{"heightCm": 150, "pallets": 3, "palletAlign": "left"}, {"heightCm": 120}, {"heightCm": 110}]},
                   {"widthCm": 267, "levels": [{"heightCm": 150, "pallets": 3, "palletAlign": "left"}, {"heightCm": 120}, {"heightCm": 110}]}]';
  _t3 uuid;
  _t2 uuid;
  _t1 uuid;
  _corner uuid;
  _base uuid;
  _case record;
  _i integer := 0;
begin
  -- Už doplnené (alebo má vlastný plán) – nič.
  if exists (select 1 from public.warehouse_spots where company_id = _company) then
    return;
  end if;

  insert into public.warehouses (company_id, length_cm, width_cm) values (_company, 1200, 1000)
  on conflict (company_id) do nothing;
  update public.warehouses set rack_types = jsonb_build_array(jsonb_build_object('id', gen_random_uuid(), 'name', 'Paletový 2 polia', 'depthCm', 110, 'bays', _bays))
  where company_id = _company;

  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, bays) values (_company, 'Regál A', 'rack', 100, 80, 561, 110, 3, _bays) returning id into _rack_a;
  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, bays) values (_company, 'Regál B', 'rack', 100, 320, 561, 110, 3, _bays) returning id into _rack_b;
  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, material) values (_company, 'Paleta 1', 'pallet', 820, 100, 120, 80, 1, 'wood') returning id into _pallet;
  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, material) values
    (_company, 'Paleta 2', 'pallet', 960, 100, 120, 80, 1, 'plastic'),
    (_company, 'Hliník', 'truss', 780, 360, 380, 240, 1, null),
    (_company, 'Kancelária', 'room', 0, 700, 450, 300, 1, null),
    (_company, 'Brána', 'door', 550, 985, 300, 15, 1, null),
    (_company, 'Okno', 'window', 1185, 200, 15, 150, 1, null),
    (_company, 'Stĺp', 'column', 680, 640, 40, 40, 1, null);

  -- Cases na regáloch: štyri na palety dole v Regáli A, dva na druhú policu, jeden na paletu na zemi.
  for _case in select id from public.cases where company_id = _company and deleted_at is null order by name limit 7 loop
    _i := _i + 1;
    if _i <= 4 then
      update public.cases set spot_id = _rack_a, spot_bay = 1, spot_level = 1, spot_pallet = null where id = _case.id;
    elsif _i <= 6 then
      update public.cases set spot_id = _rack_a, spot_bay = 1, spot_level = 2, spot_pallet = null where id = _case.id;
    else
      update public.cases set spot_id = _pallet, spot_level = null, spot_bay = null where id = _case.id;
    end if;
  end loop;

  -- Hliník (truss F34) a jeho stohy v sklade.
  insert into public.equipment (company_id, name, kind, quantity, manufacturer, model, attributes) values (_company, 'F34 3 m', 'truss', 8, 'Ukážka', 'F34', '{"trussType": "point4", "trussShape": "straight", "lengthM": 3}') returning id into _t3;
  insert into public.equipment (company_id, name, kind, quantity, manufacturer, model, attributes) values (_company, 'F34 2 m', 'truss', 8, 'Ukážka', 'F34', '{"trussType": "point4", "trussShape": "straight", "lengthM": 2}') returning id into _t2;
  insert into public.equipment (company_id, name, kind, quantity, manufacturer, model, attributes) values (_company, 'F34 1 m', 'truss', 6, 'Ukážka', 'F34', '{"trussType": "point4", "trussShape": "straight", "lengthM": 1}') returning id into _t1;
  insert into public.equipment (company_id, name, kind, quantity, manufacturer, model, attributes) values (_company, 'Roh 2-way 90°', 'truss', 4, 'Ukážka', 'F34', '{"trussType": "point4", "trussShape": "corner"}') returning id into _corner;
  insert into public.equipment (company_id, name, kind, quantity, manufacturer, model, attributes) values (_company, 'Base plate 600×600', 'truss', 4, 'Ukážka', '', '{"trussType": "accessory"}') returning id into _base;
  update public.warehouses set truss_layout = jsonb_build_object('cellCm', 35, 'cols', 8, 'rows', 4, 'stacks', jsonb_build_array(
    jsonb_build_object('col', 0, 'row', 0, 'pieces', jsonb_build_array(_t3)),
    jsonb_build_object('col', 1, 'row', 0, 'pieces', jsonb_build_array(_t3)),
    jsonb_build_object('col', 2, 'row', 0, 'pieces', jsonb_build_array(_t2, _t1)),
    jsonb_build_object('col', 3, 'row', 0, 'pieces', jsonb_build_array(_t2)),
    jsonb_build_object('col', 0, 'row', 1, 'pieces', jsonb_build_array(_t1, _t1)),
    jsonb_build_object('col', 5, 'row', 2, 'pieces', jsonb_build_array(_base, _base, _corner, _corner))
  )) where company_id = _company;

  -- Bezdrôtový systém s dvoma druhmi vysielačov.
  insert into public.equipment (company_id, name, kind, quantity, manufacturer, model, attributes) values
    (_company, 'Ukážka RX4 – 2× HT1, BP2', 'audio', 1, 'Ukážka', 'RX4 + HT1 + BP2',
     '{"audioType": "wireless", "rfRange": "470–790 MHz", "wirelessRx": "RX4", "wirelessTxs": [{"kind": "handheld", "model": "HT1", "count": 2}, {"kind": "bodypack", "model": "BP2", "count": 2}]}');

  -- Činnosti pred / na / po evente; kontrola hliníka patrí skladníkom.
  insert into public.company_duty_types (company_id, name, sort, phase, owner_roles) values
    (_company, 'Nakladanie', 1, 'before', '{}'),
    (_company, 'Stavba pódia', 2, 'event', '{}'),
    (_company, 'Vykladanie', 3, 'after', '{}'),
    (_company, 'Kontrola a naskladnenie hliníka', 4, 'after', '{skladnik}'),
    (_company, 'Kontrola kabeláže', 5, 'after', '{skladnik}')
  on conflict do nothing;
end;
$$;
revoke execute on function public.seed_demo_v7(uuid) from public, anon, authenticated;

create or replace function public.create_demo_company()
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select id into _id from public.companies where demo_owner = auth.uid();
  if _id is not null then
    return _id;
  end if;
  insert into public.companies (name, created_by, demo_owner) values ('DEMO – Ukážková firma', auth.uid(), auth.uid()) returning id into _id;
  insert into public.company_members (company_id, user_id, role) values (_id, auth.uid(), 'admin');
  perform public.seed_demo_company(_id);
  perform public.seed_demo_extras(_id, auth.uid());
  perform public.seed_demo_v4(_id, auth.uid());
  perform public.seed_demo_v46(_id);
  perform public.seed_demo_v7(_id);
  return _id;
end;
$$;

-- Existujúce demo firmy doplniť.
do $$
declare
  c record;
begin
  for c in select id from public.companies where demo_owner is not null loop
    begin
      perform public.seed_demo_v7(c.id);
    exception when others then
      raise notice 'Demo % sa nepodarilo doplniť: %', c.id, sqlerrm;
    end;
  end loop;
end;
$$;

-- ===== 0143_db_tuning.sql =====
-- RigTrack 7.15: rýchlosť a upratanie databázy podľa Supabase Advisors. Oprávnenia sa nemenia – kto čo smel vidieť
-- a meniť, smie aj po migrácii. Všetko je napísané všeobecne (podľa katalógu), takže opakované spustenie
-- supabase/update-all.sql staršie pravidlá opäť upraví a nič sa nezdvojí.
--
-- 1) Tabuľky s pravidlom „_select“ a pravidlom „for all“ (zápis): pri čítaní sa kontrolovali obe. Podmienka zápisu
--    sa pridá do pravidla na čítanie (OR – rovnaký výsledok) a pravidlo „for all“ sa rozdelí na insert / update /
--    delete s rovnakými podmienkami.
-- 2) auth.uid() v pravidlách → (select auth.uid()): vyhodnotí sa raz na dopyt, nie pri každom riadku.
-- 3) Indexy pre cudzie kľúče, ktoré žiadny index nepokrýva (rýchlejšie spojenia a mazanie).
-- 4) Funkcie triggerov sa nedajú volať cez API (spúšťa ich len databáza; oprávnenie pri spustení triggera netreba).
-- 5) Rozšírenie pg_net zo schémy public do schémy extensions. Funkcie net.* vlastní v Supabase supabase_admin,
--    takže ich oprávnenia ostávajú podľa Supabase; schéma net nie je vystavená cez API.

-- 1) Zlúčenie pravidiel na čítanie.
do $$
declare
  t record;
  a record;
  s record;
  _roles text;
  _check text;
begin
  for t in
    select tablename from pg_policies
    where schemaname = 'public' and permissive = 'PERMISSIVE'
    group by tablename
    having count(*) filter (where cmd = 'ALL') = 1 and count(*) filter (where cmd = 'SELECT') = 1
  loop
    select * into a from pg_policies where schemaname = 'public' and tablename = t.tablename and permissive = 'PERMISSIVE' and cmd = 'ALL';
    select * into s from pg_policies where schemaname = 'public' and tablename = t.tablename and permissive = 'PERMISSIVE' and cmd = 'SELECT';
    if a.roles is distinct from s.roles or a.qual is null or s.qual is null then
      continue;
    end if;
    select string_agg(quote_ident(r), ', ') into _roles from unnest(a.roles) r;
    _check := coalesce(a.with_check, a.qual);
    if position(a.qual in s.qual) = 0 then
      execute format('alter policy %I on public.%I using ((%s) or (%s))', s.policyname, t.tablename, s.qual, a.qual);
    end if;
    execute format('drop policy if exists %I on public.%I', a.policyname || '_insert', t.tablename);
    execute format('drop policy if exists %I on public.%I', a.policyname || '_update', t.tablename);
    execute format('drop policy if exists %I on public.%I', a.policyname || '_delete', t.tablename);
    execute format('create policy %I on public.%I for insert to %s with check (%s)', a.policyname || '_insert', t.tablename, _roles, _check);
    execute format('create policy %I on public.%I for update to %s using (%s) with check (%s)', a.policyname || '_update', t.tablename, _roles, a.qual, _check);
    execute format('create policy %I on public.%I for delete to %s using (%s)', a.policyname || '_delete', t.tablename, _roles, a.qual);
    execute format('drop policy %I on public.%I', a.policyname, t.tablename);
  end loop;
end;
$$;

-- 2) auth.uid() raz na dopyt.
create or replace function public.rt_wrap_uid(_expr text)
returns text language sql immutable set search_path = '' as $$
  select replace(replace(replace(_expr, '( SELECT auth.uid() AS uid)', '__rt_uid__'), 'auth.uid()', '( SELECT auth.uid() AS uid)'), '__rt_uid__', '( SELECT auth.uid() AS uid)')
$$;
revoke execute on function public.rt_wrap_uid(text) from public, anon, authenticated;

do $$
declare
  p record;
  _using text;
  _check text;
  _sql text;
begin
  for p in
    select schemaname, tablename, policyname, qual, with_check from pg_policies
    where schemaname = 'public'
      and (replace(coalesce(qual, ''), '( SELECT auth.uid() AS uid)', '') like '%auth.uid()%'
        or replace(coalesce(with_check, ''), '( SELECT auth.uid() AS uid)', '') like '%auth.uid()%')
  loop
    _using := public.rt_wrap_uid(p.qual);
    _check := public.rt_wrap_uid(p.with_check);
    _sql := format('alter policy %I on %I.%I', p.policyname, p.schemaname, p.tablename);
    if _using is not null then
      _sql := _sql || ' using (' || _using || ')';
    end if;
    if _check is not null then
      _sql := _sql || ' with check (' || _check || ')';
    end if;
    execute _sql;
  end loop;
end;
$$;

-- 3) Indexy pre cudzie kľúče.
do $$
declare
  fk record;
  _cols text;
  _name text;
begin
  for fk in
    select c.conrelid, rel.relname, c.conkey
    from pg_constraint c
    join pg_class rel on rel.oid = c.conrelid
    join pg_namespace n on n.oid = rel.relnamespace
    where c.contype = 'f' and n.nspname = 'public'
      and not exists (
        select 1 from pg_index i
        where i.indrelid = c.conrelid
          and (string_to_array(i.indkey::text, ' ')::int2[])[1:cardinality(c.conkey)] @> c.conkey
          and (string_to_array(i.indkey::text, ' ')::int2[])[1:cardinality(c.conkey)] <@ c.conkey
      )
  loop
    select string_agg(quote_ident(att.attname), ', ' order by k.ord), string_agg(att.attname, '_' order by k.ord)
    into _cols, _name
    from unnest(fk.conkey) with ordinality k(attnum, ord)
    join pg_attribute att on att.attrelid = fk.conrelid and att.attnum = k.attnum;
    _name := left(fk.relname || '_' || _name, 56) || '_fk_idx';
    execute format('create index if not exists %I on public.%I (%s)', _name, fk.relname, _cols);
  end loop;
end;
$$;

-- 4) Funkcie triggerov nie sú pre API.
do $$
declare
  f record;
  _roles text := 'public';
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    _roles := _roles || ', anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    _roles := _roles || ', authenticated';
  end if;
  for f in
    select p.oid::regprocedure as fn from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prorettype = 'trigger'::regtype
  loop
    execute format('revoke execute on function %s from %s', f.fn, _roles);
  end loop;
end;
$$;

-- 5) pg_net do schémy extensions (rozšírenie sa nedá presunúť – zmaže sa a vytvorí znova; rozpracované požiadavky
--    sa stratia, nové upozornenia idú hneď ďalej).
do $$
declare
  f record;
begin
  if exists (select 1 from pg_extension e join pg_namespace n on n.oid = e.extnamespace where e.extname = 'pg_net' and n.nspname = 'public') then
    create schema if not exists extensions;
    drop extension pg_net;
    create extension pg_net with schema extensions;
  end if;
  if exists (select 1 from pg_namespace where nspname = 'net') then
    -- Volať smie databáza (postgres – push), service_role a Database Webhooky (supabase_functions_admin).
    for f in select p.oid::regprocedure as fn from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'net' loop
      execute format('grant execute on function %s to postgres, service_role', f.fn);
      if exists (select 1 from pg_roles where rolname = 'supabase_functions_admin') then
        execute format('grant execute on function %s to supabase_functions_admin', f.fn);
      end if;
      execute format('revoke execute on function %s from public, anon, authenticated', f.fn);
    end loop;
    grant usage on schema net to postgres, service_role;
  end if;
exception when others then
  raise notice 'pg_net sa nepodarilo presunúť: %', sqlerrm;
end;
$$;

-- ===== 0144_truss_on_place.sql =====
-- RigTrack 7.16: hliník nie je samostatný druh miesta – leží na bežnom Mieste spolu s cases. Miesto s hliníkom je
-- v rozložení hliníka (warehouses.truss_layout.spotId). Staré miesta druhu „truss“ sa zmenia na Miesto (zone) a prvé
-- z nich sa zapíše ako miesto hliníka. Druh „truss“ ostáva v kontrole hodnôt kvôli starším zálohám.

update public.warehouses w
set truss_layout = coalesce(w.truss_layout, '{}'::jsonb) || jsonb_build_object('spotId', s.id)
from (
  select distinct on (company_id) company_id, id from public.warehouse_spots where kind = 'truss' order by company_id, created_at
) s
where s.company_id = w.company_id and coalesce(w.truss_layout ->> 'spotId', '') = '';

update public.warehouse_spots set kind = 'zone' where kind = 'truss';

-- Demo: miesto „Hliník a cases“.
create or replace function public.seed_demo_v7(_company uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  _rack_a uuid;
  _rack_b uuid;
  _pallet uuid;
  _bays jsonb := '[{"widthCm": 267, "levels": [{"heightCm": 150, "pallets": 3, "palletAlign": "left"}, {"heightCm": 120}, {"heightCm": 110}]},
                   {"widthCm": 267, "levels": [{"heightCm": 150, "pallets": 3, "palletAlign": "left"}, {"heightCm": 120}, {"heightCm": 110}]}]';
  _t3 uuid;
  _t2 uuid;
  _t1 uuid;
  _corner uuid;
  _base uuid;
  _case record;
  _i integer := 0;
begin
  -- Už doplnené (alebo má vlastný plán) – nič.
  if exists (select 1 from public.warehouse_spots where company_id = _company) then
    return;
  end if;

  insert into public.warehouses (company_id, length_cm, width_cm) values (_company, 1200, 1000)
  on conflict (company_id) do nothing;
  update public.warehouses set rack_types = jsonb_build_array(jsonb_build_object('id', gen_random_uuid(), 'name', 'Paletový 2 polia', 'depthCm', 110, 'bays', _bays))
  where company_id = _company;

  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, bays) values (_company, 'Regál A', 'rack', 100, 80, 561, 110, 3, _bays) returning id into _rack_a;
  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, bays) values (_company, 'Regál B', 'rack', 100, 320, 561, 110, 3, _bays) returning id into _rack_b;
  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, material) values (_company, 'Paleta 1', 'pallet', 820, 100, 120, 80, 1, 'wood') returning id into _pallet;
  insert into public.warehouse_spots (company_id, name, kind, x, y, length, width, levels, material) values
    (_company, 'Paleta 2', 'pallet', 960, 100, 120, 80, 1, 'plastic'),
    (_company, 'Hliník a cases', 'zone', 780, 360, 380, 240, 1, null),
    (_company, 'Kancelária', 'room', 0, 700, 450, 300, 1, null),
    (_company, 'Brána', 'door', 550, 985, 300, 15, 1, null),
    (_company, 'Okno', 'window', 1185, 200, 15, 150, 1, null),
    (_company, 'Stĺp', 'column', 680, 640, 40, 40, 1, null);

  -- Cases na regáloch: štyri na palety dole v Regáli A, dva na druhú policu, jeden na paletu na zemi.
  for _case in select id from public.cases where company_id = _company and deleted_at is null order by name limit 7 loop
    _i := _i + 1;
    if _i <= 4 then
      update public.cases set spot_id = _rack_a, spot_bay = 1, spot_level = 1, spot_pallet = null where id = _case.id;
    elsif _i <= 6 then
      update public.cases set spot_id = _rack_a, spot_bay = 1, spot_level = 2, spot_pallet = null where id = _case.id;
    else
      update public.cases set spot_id = _pallet, spot_level = null, spot_bay = null where id = _case.id;
    end if;
  end loop;

  -- Hliník (truss F34) a jeho stohy v sklade.
