-- ===== 0165_catalog_feedback.sql =====
-- 0165: spätná väzba firiem k databáze techniky.
-- • „Údaje sú správne“ – firma pri modeli z databázy potvrdí, že údaje sedia (návrh na overenie).
-- • „Navrhovaná zmena“ – firma pri modeli z databázy zmenila alebo doplnila údaje; vývojár zmenu prijme do databázy
--   alebo zamietne. V návrhu sú len zmenené / doplnené technické údaje.
-- • Koľko firiem a kusov model používa – vývojár vidí, čo overovať najskôr (len počty, nikdy názvy firiem).
-- Všetko čítajú a vybavujú len vývojári cez funkcie; firma vidí len svoje návrhy (RLS z 0146).

alter table public.equipment_catalog_submissions
  add column if not exists type text not null default 'new';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'equipment_catalog_submissions_type_check') then
    alter table public.equipment_catalog_submissions
      add constraint equipment_catalog_submissions_type_check check (type in ('new', 'confirm', 'correction'));
  end if;
end;
$$;
create index if not exists equipment_catalog_submissions_feedback_idx
  on public.equipment_catalog_submissions (catalog_id, type) where status = 'pending' and type <> 'new';

-- Nový model mimo databázy (ako v 0146) – len typ „new“.
create or replace function public.submit_catalog_entry(_company_id uuid, _kind text, _manufacturer text, _model text, _name text, _attributes jsonb)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _id uuid;
  _maker text := trim(coalesce(_manufacturer, ''));
  _mod text := trim(coalesce(_model, ''));
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if not public.can(_company_id, 'equipment.edit') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if _maker = '' or char_length(_maker) > 80 or char_length(_mod) > 80 or _attributes is null or jsonb_typeof(_attributes) <> 'object' then
    raise exception 'Invalid entry' using errcode = '22023';
  end if;
  if exists (select 1 from public.equipment_catalog c where c.kind = _kind and lower(c.manufacturer) = lower(_maker) and lower(c.model) = lower(_mod)) then
    return null;
  end if;
  select id into _id from public.equipment_catalog_submissions s
  where s.company_id = _company_id and s.status = 'pending' and s.type = 'new' and s.kind = _kind and lower(s.manufacturer) = lower(_maker) and lower(s.model) = lower(_mod);
  if _id is not null then
    update public.equipment_catalog_submissions set attributes = _attributes, name = left(coalesce(_name, ''), 200) where id = _id;
    return _id;
  end if;
  if (select count(*) from public.equipment_catalog_submissions s where s.company_id = _company_id and s.status = 'pending') >= 300 then
    raise exception 'Too many pending entries' using errcode = '54000';
  end if;
  insert into public.equipment_catalog_submissions (company_id, kind, manufacturer, model, name, attributes)
  values (_company_id, _kind, _maker, _mod, left(coalesce(_name, ''), 200), _attributes)
  returning id into _id;
  return _id;
end;
$$;

-- Potvrdenie alebo zmena k modelu v databáze. Overený model sa nepotvrdzuje; rovnaký návrh firmy sa len aktualizuje.
create or replace function public.submit_catalog_feedback(_company_id uuid, _catalog_id uuid, _type text, _attributes jsonb)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  _id uuid;
  _entry public.equipment_catalog;
  _data jsonb := coalesce(_attributes, '{}'::jsonb);
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if not public.can(_company_id, 'equipment.edit') then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  if _type not in ('confirm', 'correction') or jsonb_typeof(_data) <> 'object' or pg_column_size(_data) > 8000 then
    raise exception 'Invalid entry' using errcode = '22023';
  end if;
  select * into _entry from public.equipment_catalog where id = _catalog_id;
  if _entry.id is null then
    raise exception 'Invalid entry' using errcode = '22023';
  end if;
  if _type = 'confirm' then
    if _entry.verified then
      return null;
    end if;
    _data := '{}'::jsonb;
  elsif _data = '{}'::jsonb then
    return null;
  end if;
  select id into _id from public.equipment_catalog_submissions s
  where s.company_id = _company_id and s.status = 'pending' and s.type = _type and s.catalog_id = _catalog_id;
  if _id is not null then
    update public.equipment_catalog_submissions set attributes = _data, created_at = now() where id = _id;
    return _id;
  end if;
  if (select count(*) from public.equipment_catalog_submissions s where s.company_id = _company_id and s.status = 'pending') >= 300 then
    raise exception 'Too many pending entries' using errcode = '54000';
  end if;
  insert into public.equipment_catalog_submissions (company_id, kind, manufacturer, model, attributes, type, catalog_id)
  values (_company_id, _entry.kind, _entry.manufacturer, _entry.model, _data, _type, _catalog_id)
  returning id into _id;
  return _id;
end;
$$;

-- Fronta nových modelov (0146) – bez potvrdení a zmien.
create or replace function public.catalog_review_queue()
returns table (id uuid, kind text, manufacturer text, model text, name text, attributes jsonb, companies bigint, submitted_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_developer() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  return query
  select distinct on (s.kind, lower(s.manufacturer), lower(s.model))
    s.id, s.kind, s.manufacturer, s.model, s.name, s.attributes,
    (select count(distinct o.company_id) from public.equipment_catalog_submissions o
      where o.status = 'pending' and o.type = 'new' and o.kind = s.kind and lower(o.manufacturer) = lower(s.manufacturer) and lower(o.model) = lower(s.model)),
    s.created_at
  from public.equipment_catalog_submissions s
  where s.status = 'pending' and s.type = 'new'
  order by s.kind, lower(s.manufacturer), lower(s.model), s.created_at desc;
end;
$$;

-- Potvrdenia a zmeny pre vývojára: jeden riadok na model a typ (zmeny jednotlivo, každá firma môže navrhnúť inú).
create or replace function public.catalog_feedback_queue()
returns table (id uuid, catalog_id uuid, type text, attributes jsonb, companies bigint, submitted_at timestamptz)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_developer() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  return query
  select s.id, s.catalog_id, s.type, s.attributes,
    case when s.type = 'confirm' then
      (select count(distinct o.company_id) from public.equipment_catalog_submissions o
        where o.status = 'pending' and o.type = 'confirm' and o.catalog_id = s.catalog_id)
    else 1::bigint end,
    s.created_at
  from public.equipment_catalog_submissions s
  where s.status = 'pending' and s.type <> 'new' and s.catalog_id is not null
    and (s.type = 'correction' or s.id = (
      select o.id from public.equipment_catalog_submissions o
      where o.status = 'pending' and o.type = 'confirm' and o.catalog_id = s.catalog_id
      order by o.created_at desc limit 1))
  order by s.created_at desc
  limit 500;
end;
$$;

-- Vybaviť: potvrdenie = model overený; zmena = údaje (upravené vývojárom) sa zlúčia do modelu a model je overený.
-- Zamietnutie len uzavrie návrh. Potvrdenia sa uzavrú všetky naraz.
create or replace function public.resolve_catalog_feedback(_submission_id uuid, _accept boolean, _attributes jsonb default null)
returns void language plpgsql security definer set search_path = '' as $$
declare
  _source public.equipment_catalog_submissions;
  _data jsonb;
begin
  if not public.is_developer() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  select * into _source from public.equipment_catalog_submissions where id = _submission_id and type <> 'new';
  if _source.id is null or _accept is null then
    raise exception 'Invalid entry' using errcode = '22023';
  end if;
  if _accept and _source.catalog_id is not null then
    _data := coalesce(_attributes, _source.attributes, '{}'::jsonb);
    if jsonb_typeof(_data) <> 'object' then
      raise exception 'Invalid entry' using errcode = '22023';
    end if;
    update public.equipment_catalog
    set attributes = case when _source.type = 'correction' then attributes || _data else attributes end,
        verified = true, verified_at = now(), verified_by = (select auth.uid()), updated_at = now()
    where id = _source.catalog_id;
  end if;
  update public.equipment_catalog_submissions s
  set status = case when _accept then 'approved' else 'rejected' end, reviewed_at = now()
  where s.status = 'pending' and (s.id = _submission_id or (_source.type = 'confirm' and s.type = 'confirm' and s.catalog_id = _source.catalog_id));
end;
$$;

-- Koľko firiem a kusov používa model z databázy (podľa výrobcu a modelu techniky). Len počty.
create or replace function public.catalog_usage()
returns table (catalog_id uuid, companies bigint, pieces bigint)
language plpgsql stable security definer set search_path = '' as $$
begin
  if not public.is_developer() then
    raise exception 'Not allowed' using errcode = '42501';
  end if;
  return query
  select c.id, count(distinct e.company_id), coalesce(sum(e.quantity), 0)::bigint
  from public.equipment_catalog c
  join public.equipment e
    on e.kind = c.kind and lower(trim(e.manufacturer)) = lower(c.manufacturer) and lower(trim(e.model)) = lower(c.model)
  where e.deleted_at is null and trim(e.manufacturer) <> ''
  group by c.id;
end;
$$;

revoke execute on function public.submit_catalog_feedback(uuid, uuid, text, jsonb), public.catalog_feedback_queue(),
  public.resolve_catalog_feedback(uuid, boolean, jsonb), public.catalog_usage() from public, anon;
grant execute on function public.submit_catalog_feedback(uuid, uuid, text, jsonb), public.catalog_feedback_queue(),
  public.resolve_catalog_feedback(uuid, boolean, jsonb), public.catalog_usage() to authenticated;

-- ===== 0166_event_power_plans.sql =====
-- 0166: elektrika eventu po miestach.
-- K eventu sa uloží plán: miesta (strecha, rampy, pódium, zvuk…) s technikou z eventu, ďalší odber
-- a elektrocentrály (aj požičané od inej firmy). Odporúčané prívody a dimmery sa rátajú v appke.
-- Čítajú tí, čo vidia eventy (aj posádka eventu), upravujú tí, čo eventy upravujú – ako plán pódia (0095).

create table if not exists public.event_power_plans (
  company_id uuid not null,
  event_id uuid primary key,
  plan jsonb not null check (jsonb_typeof(plan) = 'object' and char_length(plan::text) <= 60000),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid() references public.profiles (id) on delete set null,
  foreign key (company_id, event_id) references public.events (company_id, id) on delete cascade
);
create index if not exists event_power_plans_company_idx on public.event_power_plans (company_id);

alter table public.event_power_plans enable row level security;
drop policy if exists event_power_plans_select on public.event_power_plans;
drop policy if exists event_power_plans_write on public.event_power_plans;
create policy event_power_plans_select on public.event_power_plans for select to authenticated
  using (public.can(company_id, 'events.view') or public.is_event_crew(event_id));
create policy event_power_plans_write on public.event_power_plans for all to authenticated
  using (public.can(company_id, 'events.edit')) with check (public.can(company_id, 'events.edit'));
revoke all on public.event_power_plans from anon, authenticated;
grant select, insert, delete on public.event_power_plans to authenticated;
-- Firma ani event sa úpravou nemenia, len plán; kto a kedy ho zmenil, zapíše databáza.
grant update (plan) on public.event_power_plans to authenticated;

create or replace function public.event_power_plans_touch()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;
$$;
drop trigger if exists event_power_plans_touch on public.event_power_plans;
create trigger event_power_plans_touch before insert or update on public.event_power_plans
  for each row execute function public.event_power_plans_touch();

-- ===== 0167_calendar_feeds.sql =====
-- 0167: kalendár eventov do mobilu (odber cez odkaz).
-- Používateľ si vytvorí tajný odkaz a pridá ho do Google / Apple kalendára, TickTicku či Outlooku.
-- „Moje“ = eventy, kde je v posádke (a neodmietol), „všetky“ = všetky eventy firmy (len s právom vidieť eventy).
-- V databáze je len odtlačok (SHA-256) odkazu, nie odkaz samotný. Odkaz sa dá kedykoľvek zrušiť a pri
-- každom načítaní sa znova overí, že je človek stále vo firme a má oprávnenie.
-- Kalendár číta len Edge funkcia calendar-feed (služobný kľúč) – nikto iný funkciu calendar_feed_events nespustí.

create table if not exists public.calendar_feeds (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null default auth.uid() references public.profiles (id) on delete cascade,
  company_id uuid not null references public.companies (id) on delete cascade,
  scope text not null check (scope in ('mine', 'all')),
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  app_url text not null default '' check (app_url = '' or (app_url ~* '^https?://' and char_length(app_url) <= 200)),
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  unique (user_id, company_id, scope)
);
create index if not exists calendar_feeds_company_idx on public.calendar_feeds (company_id);

alter table public.calendar_feeds enable row level security;
drop policy if exists calendar_feeds_select on public.calendar_feeds;
drop policy if exists calendar_feeds_delete on public.calendar_feeds;
create policy calendar_feeds_select on public.calendar_feeds for select to authenticated using (user_id = auth.uid());
create policy calendar_feeds_delete on public.calendar_feeds for delete to authenticated using (user_id = auth.uid());
revoke all on public.calendar_feeds from anon, authenticated;
-- Odtlačok sa nečíta ani v appke; vytvára sa len cez funkciu.
grant select (id, company_id, scope, created_at, last_used_at), delete on public.calendar_feeds to authenticated;

-- Nový odkaz (starý rovnakého druhu prestane fungovať). Vráti odkaz – ukáže sa len raz.
create or replace function public.create_calendar_feed(_company_id uuid, _scope text, _app_url text)
returns text language plpgsql volatile security definer set search_path = '' as $$
declare
  _token text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if _scope not in ('mine', 'all') then
    raise exception 'Neznámy druh kalendára' using errcode = '22023';
  end if;
  if not public.is_company_member(_company_id) or (_scope = 'all' and not public.can(_company_id, 'events.view')) then
    raise exception 'Na tento kalendár nemáte oprávnenie' using errcode = 'insufficient_privilege';
  end if;
  delete from public.calendar_feeds where user_id = auth.uid() and company_id = _company_id and scope = _scope;
  insert into public.calendar_feeds (user_id, company_id, scope, token_hash, app_url)
  values (
    auth.uid(), _company_id, _scope, encode(sha256(convert_to(_token, 'UTF8')), 'hex'),
    case when coalesce(_app_url, '') ~* '^https?://' and char_length(_app_url) <= 200 then _app_url else '' end
  );
  return _token;
end;
$$;
revoke execute on function public.create_calendar_feed(uuid, text, text) from public, anon;
grant execute on function public.create_calendar_feed(uuid, text, text) to authenticated;

-- Eventy pre kalendár podľa odkazu (len pre Edge funkciu). Neplatný odkaz, odchod z firmy
-- alebo odobraté oprávnenie = prázdny kalendár.
create or replace function public.calendar_feed_events(_token text)
returns table (
  id uuid, name text, venue text, starts_on date, ends_on date, status text,
  get_in_time text, show_time text, show_end_time text, crew_role text, company_name text, scope text, app_url text
)
language plpgsql volatile security definer set search_path = '' as $$
declare
  _feed public.calendar_feeds;
begin
  if _token is null or _token !~ '^[0-9a-f]{64}$' then
    return;
  end if;
  select * into _feed from public.calendar_feeds f where f.token_hash = encode(sha256(convert_to(_token, 'UTF8')), 'hex');
  if not found then
    return;
  end if;
  -- Oprávnenia sa overia za majiteľa odkazu (rovnako ako v appke).
  perform set_config('request.jwt.claims', json_build_object('sub', _feed.user_id, 'role', 'authenticated')::text, true);
  perform set_config('request.jwt.claim.sub', _feed.user_id::text, true);
  if not public.is_company_member(_feed.company_id) or (_feed.scope = 'all' and not public.can(_feed.company_id, 'events.view')) then
    return;
  end if;
  update public.calendar_feeds set last_used_at = now() where calendar_feeds.id = _feed.id;
  return query
    select e.id, e.name, e.venue, e.starts_on, e.ends_on, e.status::text,
      coalesce(to_char(e.get_in_time, 'HH24:MI'), ''), coalesce(to_char(e.show_time, 'HH24:MI'), ''), coalesce(to_char(e.show_end_time, 'HH24:MI'), ''),
      coalesce((select string_agg(nullif(c.role, ''), ', ') from public.event_crew c where c.event_id = e.id and c.member_id = _feed.user_id), ''),
      co.name, _feed.scope, _feed.app_url
    from public.events e
    join public.companies co on co.id = e.company_id
    where e.company_id = _feed.company_id
      and e.status <> 'cancelled'
      and e.ends_on >= current_date - 90
      and (_feed.scope = 'all' or exists (
        select 1 from public.event_crew c where c.event_id = e.id and c.member_id = _feed.user_id and c.response <> 'no'
      ))
    order by e.starts_on
    limit 2000;
end;
$$;
revoke execute on function public.calendar_feed_events(text) from public, anon, authenticated;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    grant execute on function public.calendar_feed_events(text) to service_role;
  end if;
end;
$$;

-- ===== 0168_power_calendar_tuning.sql =====
-- 0168: doladenie tabuliek z 0166 a 0167 podľa pravidiel z 0143.
-- • auth.uid() sa v pravidlách vyhodnotí raz za dotaz, • čítanie a zápis majú oddelené pravidlá,
-- • cudzie kľúče majú index, • funkcia triggera sa nedá zavolať cez API.

drop policy if exists calendar_feeds_select on public.calendar_feeds;
drop policy if exists calendar_feeds_delete on public.calendar_feeds;
create policy calendar_feeds_select on public.calendar_feeds for select to authenticated using (user_id = (select auth.uid()));
create policy calendar_feeds_delete on public.calendar_feeds for delete to authenticated using (user_id = (select auth.uid()));

drop policy if exists event_power_plans_write on public.event_power_plans;
drop policy if exists event_power_plans_insert on public.event_power_plans;
drop policy if exists event_power_plans_update on public.event_power_plans;
drop policy if exists event_power_plans_delete on public.event_power_plans;
create policy event_power_plans_insert on public.event_power_plans for insert to authenticated
  with check (public.can(company_id, 'events.edit'));
create policy event_power_plans_update on public.event_power_plans for update to authenticated
  using (public.can(company_id, 'events.edit')) with check (public.can(company_id, 'events.edit'));
create policy event_power_plans_delete on public.event_power_plans for delete to authenticated
  using (public.can(company_id, 'events.edit'));

create index if not exists event_power_plans_company_event_idx on public.event_power_plans (company_id, event_id);
create index if not exists event_power_plans_updated_by_idx on public.event_power_plans (updated_by);

revoke execute on function public.event_power_plans_touch() from public, anon, authenticated;

-- ===== 0169_conflicts_skip_demo.sql =====
-- 0169: kolízie naprieč firmami (0091) bez ukážkovej firmy.
-- Ukážková firma si pri založení vytvorí vzorové eventy a zapíše do posádky toho, kto ju založil.
-- Tie nie sú skutočná práca, takže človek ani technika kvôli nim nemajú byť „v termíne v inej firme“.

create or replace function public.crew_busy_elsewhere(_company_id uuid, _from date, _to date)
returns table (member_id uuid, events integer, starts_on date, ends_on date)
language sql stable security definer set search_path = '' as $$
  select c.member_id, count(distinct e.id)::integer, min(e.starts_on), max(e.ends_on)
  from public.event_crew c
  join public.events e on e.id = c.event_id
  join public.companies co on co.id = e.company_id
  where public.can(_company_id, 'events.view')
    and c.company_id <> _company_id
    and co.demo_owner is null
    and c.member_id in (select m.user_id from public.company_members m where m.company_id = _company_id)
    and c.response <> 'no'
    and e.status <> 'cancelled'
    and e.starts_on <= _to and e.ends_on >= _from
  group by c.member_id;
$$;

create or replace function public.gear_busy_elsewhere(_company_id uuid, _from date, _to date)
returns table (equipment_id uuid, quantity integer, starts_on date, ends_on date)
language sql stable security definer set search_path = '' as $$
  select x.id, sum(ee.quantity)::integer, min(e.starts_on), max(e.ends_on)
  from public.equipment x
  join public.equipment r on coalesce(r.shared_from, r.id) = coalesce(x.shared_from, x.id) and r.company_id <> x.company_id
  join public.event_equipment ee on ee.equipment_id = r.id
  join public.events e on e.id = ee.event_id
  join public.companies co on co.id = e.company_id
  where public.can(_company_id, 'events.view')
    and x.company_id = _company_id
    and co.demo_owner is null
    and (x.shared_from is not null or exists (select 1 from public.equipment c where c.shared_from = x.id))
    and e.status <> 'cancelled'
    and e.starts_on <= _to and e.ends_on >= _from
  group by x.id;
$$;

-- ===== 0071_repair_all_columns.sql =====
-- RigTrack: oprava celej databázy (vygenerované z výslednej schémy).
-- Ak niektoré migrácie prebehli v staršej verzii z vývoja, chýbajú v tabuľkách stĺpce
-- (napr. „column vat of relation event_payments does not exist“). Tento súbor doplní každý chýbajúci stĺpec
-- vo všetkých tabuľkách a oprávnenia k nim. Existujúce dáta ani stĺpce nemení; dá sa spustiť aj viackrát.
-- Tabuľky, ktoré chýbajú úplne, nezakladá – na tie spustite príslušnú migráciu (ukáže ich check-migrations.sql).

do $repair$
begin
  if to_regclass('public.app_developers') is not null then
    execute $sql$alter table public.app_developers add column if not exists user_id uuid$sql$;
    execute $sql$alter table public.app_developers add column if not exists created_at timestamp with time zone default now() not null$sql$;
  end if;
  if to_regclass('public.attachments') is not null then
    execute $sql$alter table public.attachments add column if not exists id uuid default gen_random_uuid() not null$sql$;
    execute $sql$alter table public.attachments add column if not exists company_id uuid$sql$;
    execute $sql$alter table public.attachments add column if not exists entity_type text$sql$;
    execute $sql$alter table public.attachments add column if not exists entity_id uuid$sql$;
    execute $sql$alter table public.attachments add column if not exists name text$sql$;
    execute $sql$alter table public.attachments add column if not exists path text$sql$;
    execute $sql$alter table public.attachments add column if not exists size_bytes bigint default 0 not null$sql$;
    execute $sql$alter table public.attachments add column if not exists created_by uuid default auth.uid()$sql$;
    execute $sql$alter table public.attachments add column if not exists created_at timestamp with time zone default now() not null$sql$;
    execute $sql$alter table public.attachments add column if not exists deleted_at timestamp with time zone$sql$;
    execute $sql$alter table public.attachments add column if not exists deleted_by_name text default ''::text not null$sql$;
    execute $sql$grant insert, select, delete on public.attachments to authenticated$sql$;
  end if;
  if to_regclass('public.audit_log') is not null then
    execute $sql$alter table public.audit_log add column if not exists id bigint$sql$;
    execute $sql$alter table public.audit_log add column if not exists company_id uuid$sql$;
    execute $sql$alter table public.audit_log add column if not exists actor_id uuid$sql$;
    execute $sql$alter table public.audit_log add column if not exists actor_name text default ''::text not null$sql$;
    execute $sql$alter table public.audit_log add column if not exists action text$sql$;
    execute $sql$alter table public.audit_log add column if not exists entity text$sql$;
    execute $sql$alter table public.audit_log add column if not exists entity_id uuid$sql$;
    execute $sql$alter table public.audit_log add column if not exists label text default ''::text not null$sql$;
    execute $sql$alter table public.audit_log add column if not exists changed text[]$sql$;
    execute $sql$alter table public.audit_log add column if not exists created_at timestamp with time zone default now() not null$sql$;
    execute $sql$grant select on public.audit_log to authenticated$sql$;
  end if;
  if to_regclass('public.bug_reports') is not null then
    execute $sql$alter table public.bug_reports add column if not exists id uuid default gen_random_uuid() not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists company_id uuid$sql$;
    execute $sql$alter table public.bug_reports add column if not exists reporter_id uuid default auth.uid()$sql$;
    execute $sql$alter table public.bug_reports add column if not exists reporter_name text default ''::text not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists title text$sql$;
    execute $sql$alter table public.bug_reports add column if not exists description text default ''::text not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists page_url text default ''::text not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists app_version text default ''::text not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists user_agent text default ''::text not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists screenshot_path text default ''::text not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists status text default 'new'::text not null$sql$;
    execute $sql$alter table public.bug_reports add column if not exists response text default ''::text not null$sql$;
