  new.checked_at := now();
  new.checked_by_name := coalesce((select coalesce(nullif(trim(p.full_name), ''), p.email) from public.profiles p where p.id = auth.uid()), '');
  return new;
end;
$function$$repairfn$;
exception when others then raise notice 'Funkcia stamp_pack_check: %', sqlerrm;
end;
